import { Responsive, useContainerWidth, noCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import type { DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts } from "../types/api";

const fixedGridCompactor: Compactor = {
  ...noCompactor,
  preventCollision: true
};

type DashboardGridProps = {
  dashboard: DashboardLayout;
  editing: boolean;
  renderCell: (cell: DashboardCell) => ReactNode;
  onLayoutsChange: (layouts: DashboardResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function DashboardGrid({
  dashboard,
  editing,
  renderCell,
  onLayoutsChange,
  onUpdateCell,
  onRemoveCell
}: DashboardGridProps) {
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<DashboardBreakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => buildResponsiveCells(dashboard.cells, dashboard.layouts), [dashboard.cells, dashboard.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? dashboard.cells;
  const layouts = useMemo(() => Object.fromEntries(
    (Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]).map((breakpoint) => [
      breakpoint,
      cellsByBreakpoint[breakpoint].map(toLayoutItem)
    ])
  ) as unknown as Record<DashboardBreakpoint, Layout>, [cellsByBreakpoint]);

  const handleLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const normalized = {} as DashboardResponsiveLayouts;
    for (const breakpoint of Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]) {
      const layout = nextLayouts[breakpoint];
      if (layout) normalized[breakpoint] = mergeLayoutCells(cellsByBreakpoint[breakpoint], layout);
    }
    onLayoutsChange(normalized);
  }, [editing, cellsByBreakpoint, onLayoutsChange]);

  return (
    <div ref={containerRef as unknown as Ref<HTMLDivElement>} className={`dashboard-rgl-shell ${editing ? "is-editing" : "is-viewing"}`}>
      {mounted && (
        <Responsive
          className="dashboard-rgl"
          width={width}
          layouts={layouts}
          breakpoints={BREAKPOINTS}
          cols={BREAKPOINT_COLUMNS}
          rowHeight={dashboard.rowHeight}
          margin={[10, 10]}
          containerPadding={[0, 0]}
          dragConfig={{
            enabled: editing,
            handle: ".dashboard-drag-handle",
            cancel: ".dashboard-cell-body, input, select, .dashboard-cell-remove, a"
          }}
          resizeConfig={{
            enabled: editing,
            handles: ["se"]
          }}
          compactor={fixedGridCompactor}
          autoSize
          onBreakpointChange={(breakpoint) => setActiveBreakpoint(toDashboardBreakpoint(breakpoint))}
          onLayoutChange={handleLayoutChange}
        >
          {activeCells.map((cell) => (
            <section key={cell.id} className={`dashboard-cell dashboard-cell-${cell.viewType}`}>
              <header className="pane-header pane-header-compact dashboard-cell-header">
                {editing ? <>
                  <button type="button" className="dashboard-drag-handle" aria-label="Move cell" title="Drag to move">⋮⋮</button>
                  <input
                    value={cell.title}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value }))}
                    aria-label="Cell title"
                  />
                  <select
                    value={cell.viewType}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, viewType: event.target.value as DashboardCell["viewType"], title: titleForDashboardView(event.target.value as DashboardCell["viewType"]) }))}
                    aria-label="Cell view type"
                  >
                    {DASHBOARD_VIEW_TYPES.map((viewType) => <option key={viewType} value={viewType}>{titleForDashboardView(viewType)}</option>)}
                  </select>
                  <button type="button" className="dashboard-cell-remove" onClick={() => onRemoveCell(cell.id)} disabled={activeCells.length <= 1} aria-label="Remove cell">×</button>
                </> : <strong className="pane-header-title">{cell.title}</strong>}
              </header>
              <div className="dashboard-cell-body">
                {renderCell(cell)}
              </div>
            </section>
          ))}
        </Responsive>
      )}
    </div>
  );
}
const BREAKPOINTS: Record<DashboardBreakpoint, number> = { desktop: 1200, tablet: 700, mobile: 0 };
const BREAKPOINT_COLUMNS: Record<DashboardBreakpoint, number> = { desktop: 24, tablet: 12, mobile: 4 };

function breakpointForWidth(width: number): DashboardBreakpoint {
  if (width >= BREAKPOINTS.desktop) return "desktop";
  if (width >= BREAKPOINTS.tablet) return "tablet";
  return "mobile";
}

function toDashboardBreakpoint(breakpoint: string): DashboardBreakpoint {
  return breakpoint === "desktop" || breakpoint === "tablet" || breakpoint === "mobile"
    ? breakpoint
    : "desktop";
}

function toLayoutItem(cell: DashboardCell): LayoutItem {
  return {
    i: cell.id,
    x: cell.grid.x,
    y: cell.grid.y,
    w: cell.grid.w,
    h: cell.grid.h,
    minW: 2,
    maxW: 48,
    minH: 3,
    maxH: 40,
    isBounded: true
  };
}

function buildResponsiveCells(cells: DashboardCell[], saved: DashboardResponsiveLayouts | undefined): Record<DashboardBreakpoint, DashboardCell[]> {
  return {
    desktop: saved?.desktop ?? cells,
    tablet: saved?.tablet ?? fallbackLayout(cells, 12, 2),
    mobile: saved?.mobile ?? fallbackLayout(cells, 4, 1)
  };
}

function fallbackLayout(cells: DashboardCell[], columns: number, columnCount: number) {
  const slotWidth = Math.floor(columns / columnCount);
  const result: DashboardCell[] = [];
  let y = 0;
  for (let index = 0; index < cells.length; index += columnCount) {
    const row = cells.slice(index, index + columnCount);
    const rowHeight = Math.max(...row.map((cell) => cell.grid.h), 3);
    row.forEach((cell, column) => {
      result.push({
        ...cell,
        grid: {
          x: column * slotWidth,
          y,
          w: slotWidth,
          h: cell.grid.h
        }
      });
    });
    y += rowHeight;
  }
  return result;
}

function mergeLayoutCells(cells: DashboardCell[], layout: Layout) {
  const positions = new Map(layout.map((item) => [item.i, item]));
  return cells.map((cell) => {
    const item = positions.get(cell.id);
    return item ? { ...cell, grid: { x: item.x, y: item.y, w: item.w, h: item.h } } : cell;
  });
}

const DASHBOARD_VIEW_TYPES: DashboardCell["viewType"][] = ["streams", "detail", "timeline", "topology", "events"];

function titleForDashboardView(viewType: DashboardCell["viewType"]) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Detail";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}
import type { FlowMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";
import { MetricChart } from "./MetricChart";

type DetailPaneProps = {
  stream: StreamState | null;
  metrics: StreamMetricsResponse | null;
  selectedFlowKey?: string | null;
  metricsRange: string;
  onChangeMetricsRange: (range: string) => void;
  mode: "overview" | "detail";
  onChangeMode: (mode: "overview" | "detail") => void;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
};

const FLOW_ROLE_ACCENTS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
  default: "#7f98b5"
};

export function DetailPane({
  stream,
  metrics,
  selectedFlowKey,
  metricsRange,
  onChangeMetricsRange,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls
}: DetailPaneProps) {
  if (!stream) {
    return <aside className="detail-pane empty-state">Select a stream to inspect bitrate and flow metrics.</aside>;
  }

  const descriptors = metrics?.descriptors ?? [];
  const visibleFlows = selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows;
  const visibleMetrics = metrics && selectedFlowKey
    ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) }
    : metrics;
  const primary = descriptors.filter((descriptor) => descriptor.category === "primary");
  const secondary = descriptors.filter((descriptor) => descriptor.category === "secondary");
  const stats = descriptors.filter((descriptor) => descriptor.category === "stat");

  return (
    <aside className={`detail-pane ${mode === "overview" ? "graph-mode" : ""}`}>
      <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <span className="kind-pill">{stream.kind}</span>
          <h2>{stream.label}</h2>
          <p>{selectedFlowKey ? "Filtered to one flow" : `${stream.flowCount} flow${stream.flowCount === 1 ? "" : "s"}`} / last seen {formatRelativeTime(stream.lastSeen)}</p>
        </div>
        <div className="detail-header-actions">
          <label className="detail-range-select">
            <span>Range</span>
            <select value={metricsRange} onChange={(event) => onChangeMetricsRange(event.target.value)}>
              <option value="24h">24h</option>
              <option value="12h">12h</option>
              <option value="6h">6h</option>
              <option value="3h">3h</option>
              <option value="1h">1h</option>
              <option value="30m">30m</option>
              <option value="10m">10m</option>
              <option value="5m">5m</option>
            </select>
          </label>
          <div className="detail-mode-tabs" role="tablist" aria-label="Detail mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Detail</button>
          </div>
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Detail width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize detail pane"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore detail pane width"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink detail pane"><span className="width-icon" aria-hidden="true" /></button>
            </div>
          )}
        </div>
      </header>

      <div className="detail-body">
        {mode === "overview" ? (
          <GraphMode
            stream={stream}
            metrics={visibleMetrics}
            visibleFlows={visibleFlows}
            descriptors={[...primary, ...secondary]}
            selectedFlowKey={selectedFlowKey}
          />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
              <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
              <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
            </div>

            <section className="flow-table-card">
              <h3>Flows</h3>
              <div className="flow-table">
                {visibleFlows.map((flow) => (
                  <div className="flow-row" key={flow.flowKey}>
                    <strong>{flow.role}</strong>
                    <span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span>
                    <span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span>
                  </div>
                ))}
              </div>
            </section>

            {stats.length > 0 && <StatsSection descriptors={stats} metrics={visibleMetrics} />}

            {!selectedFlowKey && <MetricChart title="Stream Bitrate" metric={metrics?.streamBitrate} />}

            {primary.map((descriptor) => (
              <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} />
            ))}

            {secondary.length > 0 && (
              <details className="more-metrics">
                <summary>More numeric metrics</summary>
                {secondary.slice(0, 12).map((descriptor) => (
                  <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} compact />
                ))}
              </details>
            )}
          </>
        )}
      </div>
    </aside>
  );
}

function GraphMode({
  stream,
  metrics,
  visibleFlows,
  descriptors,
  selectedFlowKey
}: {
  stream: StreamState;
  metrics: StreamMetricsResponse | null;
  visibleFlows: StreamState["flows"];
  descriptors: MetricDescriptor[];
  selectedFlowKey?: string | null;
}) {
  const nonBitrateDescriptors = descriptors
    .filter((descriptor) => descriptor.key !== "bitrate")
    .sort((a, b) => a.priority - b.priority);
  const metricByFlowKey = new Map((metrics?.flows ?? []).map((flow) => [flow.flowKey, flow]));
  const streamBitrate = metrics?.streamBitrate;

  return (
    <div className="graph-mode-layout">
      <section className="graph-summary-band">
        <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
        <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
        <Stat label="Flows" value={String(visibleFlows.length)} />
