}: DetailPaneProps) {
  if (!stream) {
    return <aside className="detail-pane empty-state">Select a stream to inspect bitrate and flow metrics.</aside>;
  }

  const descriptors = metrics?.descriptors ?? [];
  const visibleFlows = selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows;
  const visibleMetrics = metrics && selectedFlowKey
    ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) }
    : metrics;
  const primary = descriptors.filter((descriptor) => descriptor.category === "primary");
  const secondary = descriptors.filter((descriptor) => descriptor.category === "secondary");
  const stats = descriptors.filter((descriptor) => descriptor.category === "stat");

  return (
    <aside className={`detail-pane ${mode === "overview" ? "graph-mode" : ""}`}>
      <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <span className="kind-pill">{stream.kind}</span>
          <h2>{stream.label}</h2>
          <p>{selectedFlowKey ? "Filtered to one flow" : `${stream.flowCount} flow${stream.flowCount === 1 ? "" : "s"}`} / last seen {formatRelativeTime(stream.lastSeen)}</p>
        </div>
        <div className="detail-header-actions">
          <label className="detail-range-select">
            <span>Range</span>
            <select value={metricsRange} onChange={(event) => onChangeMetricsRange(event.target.value)}>
              <option value="24h">24h</option>
              <option value="12h">12h</option>
              <option value="6h">6h</option>
              <option value="3h">3h</option>
              <option value="1h">1h</option>
              <option value="30m">30m</option>
              <option value="10m">10m</option>
              <option value="5m">5m</option>
            </select>
          </label>
          <div className="detail-mode-tabs" role="tablist" aria-label="Detail mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Detail</button>
          </div>
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Detail width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize detail pane"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore detail pane width"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink detail pane"><span className="width-icon" aria-hidden="true" /></button>
            </div>
          )}
        </div>
      </header>

      <div className="detail-body">
        {mode === "overview" ? (
          <GraphMode
            stream={stream}
            metrics={visibleMetrics}
            visibleFlows={visibleFlows}
            descriptors={[...primary, ...secondary]}
            selectedFlowKey={selectedFlowKey}
          />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
              <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
              <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
            </div>

            <section className="flow-table-card">
              <h3>Flows</h3>
              <div className="flow-table">
                {visibleFlows.map((flow) => (
                  <div className="flow-row" key={flow.flowKey}>
                    <strong>{flow.role}</strong>
                    <span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span>
                    <span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span>
                  </div>
                ))}
              </div>
            </section>

            {stats.length > 0 && <StatsSection descriptors={stats} metrics={visibleMetrics} />}

            {!selectedFlowKey && <MetricChart title="Stream Bitrate" metric={metrics?.streamBitrate} />}

            {primary.map((descriptor) => (
              <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} />
            ))}

            {secondary.length > 0 && (
              <details className="more-metrics">
                <summary>More numeric metrics</summary>
                {secondary.slice(0, 12).map((descriptor) => (
                  <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} compact />
                ))}
              </details>
            )}
          </>
        )}
      </div>
    </aside>
  );
}

function GraphMode({
  stream,
  metrics,
  visibleFlows,
  descriptors,
  selectedFlowKey
}: {
  stream: StreamState;
  metrics: StreamMetricsResponse | null;
  visibleFlows: StreamState["flows"];
  descriptors: MetricDescriptor[];
  selectedFlowKey?: string | null;
}) {
  const nonBitrateDescriptors = descriptors
    .filter((descriptor) => descriptor.key !== "bitrate")
    .sort((a, b) => a.priority - b.priority);
  const metricByFlowKey = new Map((metrics?.flows ?? []).map((flow) => [flow.flowKey, flow]));
  const streamBitrate = metrics?.streamBitrate;

  return (
    <div className="graph-mode-layout">
      <section className="graph-summary-band">
        <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
        <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
        <Stat label="Flows" value={String(visibleFlows.length)} />
        <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
      </section>

      {!selectedFlowKey && (
        <section className="graph-hero-card">
          <MetricChart title="Stream Bitrate" metric={streamBitrate} height={96} compact fillHeight color="#66d9ef" />
        </section>
      )}

      <section className={`graph-flow-grid ${visibleFlows.length === 1 ? "single" : ""}`}>
        {visibleFlows.map((flow) => {
          const flowMetrics = metricByFlowKey.get(flow.flowKey);
          const charts = [
            flowMetrics?.metrics.bitrate ? { key: "bitrate", label: "Bitrate", metric: flowMetrics.metrics.bitrate } : null,
            ...nonBitrateDescriptors
              .map((descriptor) => {
                const metric = flowMetrics?.metrics[descriptor.key];
                return metric ? { key: descriptor.key, label: descriptor.label, metric } : null;
              })
              .filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item))
          ].filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item));

          return (
            <GraphFlowCard
              key={flow.flowKey}
              flow={flow}
              metrics={flowMetrics}
              charts={charts}
            />
          );
        })}
      </section>
    </div>
  );
}

function GraphFlowCard({
  flow,
  metrics,
  charts
}: {
  flow: StreamState["flows"][number];
  metrics?: FlowMetricsResponse;
  charts: Array<{ key: string; label: string; metric: TimeSeriesMetric }>;
}) {
  const accent = flowAccent(flow.role);
  const bitrate = metrics?.metrics.bitrate?.points.at(-1)?.avg
    ?? metrics?.metrics.bitrate?.points.at(-1)?.value
    ?? flow.metrics.bitrate?.value
    ?? flow.metrics.bitrate?.avg;

  return (
    <section className="graph-flow-card" style={{ borderTopColor: accent }}>
      <div className="graph-flow-card-header">
        <div>
          <strong>{flow.role}</strong>
          <p>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</p>
        </div>
        <span className="graph-flow-rate">{formatBitrate(bitrate)}</span>
      </div>
      <div className={`graph-card-grid ${charts.length === 1 ? "single" : ""}`}>
        {charts.map((chart) => (
          <MetricChart
            key={`${flow.flowKey}:${chart.key}`}
            title={chart.label}
            metric={chart.metric}
            height={chart.key === "bitrate" ? 64 : 52}
            compact
            fillHeight
            color={chart.key === "bitrate" ? accent : colorForMetric(chart.key)}
          />
        ))}
      </div>
    </section>
  );
}

function FlowMetricGroup({ descriptor, metrics, compact = false }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse | null; compact?: boolean }) {
  const flowMetrics = metrics?.flows
    .map((flow) => ({ flow, metric: flow.metrics[descriptor.key] }))
    .filter((item): item is { flow: NonNullable<typeof metrics>["flows"][number]; metric: TimeSeriesMetric } => Boolean(item.metric));

  if (!flowMetrics || flowMetrics.length === 0) return null;

  return (
    <section className={compact ? "metric-group compact" : "metric-group"}>
      <h3>{descriptor.label}</h3>
      <div className="chart-stack">
        {flowMetrics.map(({ flow, metric }) => (
          <MetricChart key={`${flow.flowKey}:${descriptor.key}`} title={flow.label} metric={metric} height={compact ? 130 : 170} color={colorForMetric(descriptor.key)} />
        ))}
      </div>
    </section>
  );
}

function StatsSection({ descriptors, metrics }: { descriptors: MetricDescriptor[]; metrics: StreamMetricsResponse | null }) {
  const values = metrics?.flows.flatMap((flow) =>
    descriptors.flatMap((descriptor) => {
      const latest = flow.metrics[descriptor.key]?.points.at(-1);
      const value = latest?.value ?? latest?.avg;
      return value === undefined ? [] : [{ key: `${flow.flowKey}:${descriptor.key}`, label: `${flow.role} ${descriptor.label}`, value }];
    })
  ) ?? [];

  if (values.length === 0) return null;
  return (
    <section className="stats-section">
      <h3>Stats</h3>
      <div className="stats-grid">
        {values.slice(0, 18).map((item) => <Stat key={item.key} label={item.label} value={formatNumber(item.value)} />)}
      </div>
    </section>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>;
}

function flowAccent(role: string) {
  return FLOW_ROLE_ACCENTS[role] ?? FLOW_ROLE_ACCENTS.default;
}

function colorForMetric(key: string) {
  const palette: Record<string, string> = {
    bitrate: "#66d9ef",
    packet_rate: "#8bd17c",
    jitter: "#d6b66f",
    rtt: "#d98b7f",
    rttvar: "#c58bd6",
    bandwidth: "#7fa7d9",
    rate: "#70c7b0",
    rcvrate: "#9ca4d9",
    interval: "#d69f73",
    clock_skew: "#b5c46f",
    nak_seqno: "#d184a8"
  };
  const root = key.split(".")[0];
  return palette[root] ?? fallbackMetricColor(root);
}

function fallbackMetricColor(key: string) {
  const colors = ["#8fb8d8", "#91c7a3", "#c9b878", "#d09787", "#a995d0", "#78c2bf", "#c99ac0"];
  let hash = 0;
  for (const char of key) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return colors[hash % colors.length];
}
import type { CSSProperties } from "react";
import type { InterfaceListItem, InterfaceMetricsResponse } from "../types/api";
import { MetricChart } from "./MetricChart";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";

type InterfaceDetailPaneProps = {
  item: InterfaceListItem | null;
  metrics: InterfaceMetricsResponse | null;
  mode: "overview" | "detail";
  onChangeMode: (mode: "overview" | "detail") => void;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
};

export function InterfaceDetailPane({
  item,
  metrics,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls
}: InterfaceDetailPaneProps) {
  if (!item) {
    return <aside className="detail-pane empty-state">Select an interface or stream.</aside>;
  }

  return (
    <aside className={`detail-pane interface-detail-pane ${mode === "overview" ? "graph-mode" : ""}`}>
      <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <span className="kind-pill">NIC</span>
          <h2>{item.name}</h2>
          <p>{item.available ? "Available" : "Unavailable"} / {item.streamCount} stream{item.streamCount === 1 ? "" : "s"} / last seen {item.lastSeen ? formatRelativeTime(item.lastSeen) : "waiting"}</p>
        </div>
        <div className="detail-header-actions">
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Detail width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize detail pane"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore detail pane width"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink detail pane"><span className="width-icon" aria-hidden="true" /></button>
            </div>
          )}
          <div className="detail-mode-tabs" role="tablist" aria-label="NIC detail mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Detail</button>
          </div>
        </div>
      </header>

      <div className="detail-body">
        {mode === "overview" ? (
          <InterfaceOverview item={item} metrics={metrics} />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="RX Bitrate" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
              <Stat label="TX Bitrate" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
              <Stat label="Link" value={formatLinkSummary(item)} />
              <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
              <Stat label="Streams" value={String(item.streamCount)} />
            </div>

            <BandwidthUsagePanel item={item} />

            <section className="stats-section">
              <h3>NIC Stats</h3>
              <div className="stats-grid">
                <Stat label="RX Packets" value={formatNumber(item.rx.packets.value ?? 0)} />
                <Stat label="TX Packets" value={formatNumber(item.tx.packets.value ?? 0)} />
                <Stat label="RX Drops" value={formatNumber(item.rx.dropped.value ?? 0)} />
                <Stat label="TX Drops" value={formatNumber(item.tx.dropped.value ?? 0)} />
                <Stat label="RX Errors" value={formatNumber(item.rx.errors.value ?? 0)} />
                <Stat label="TX Errors" value={formatNumber(item.tx.errors.value ?? 0)} />
              </div>
            </section>

            <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} color="#66d9ef" />
            <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} color="#f7c873" />

            <section className="metric-group">
              <h3>Packets / Drops / Errors</h3>
              <div className="chart-stack">
                <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={150} color="#7fd4c7" />
                <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={150} color="#d8b86d" />
                <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={130} color="#d6b66f" />
                <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={130} color="#cda866" />
                <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={130} color="#d98b7f" />
                <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={130} color="#c98278" />
              </div>
            </section>
          </>
        )}
      </div>
    </aside>
  );
}

function InterfaceOverview({ item, metrics }: { item: InterfaceListItem; metrics: InterfaceMetricsResponse | null }) {
  return (
    <div className="graph-mode-layout interface-overview-layout">
      <section className="graph-summary-band">
        <Stat label="RX" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
        <Stat label="TX" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
        <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
        <Stat label="Link" value={formatLinkSummary(item)} />
        <Stat label="Drops" value={formatNumber((item.rx.dropped.value ?? 0) + (item.tx.dropped.value ?? 0))} />
        <Stat label="Errors" value={formatNumber((item.rx.errors.value ?? 0) + (item.tx.errors.value ?? 0))} />
      </section>
      <BandwidthUsagePanel item={item} compact />
      <section className="graph-card-grid interface-overview-grid">
        <MetricChart title="RX Utilization" metric={metrics?.metrics["rx.utilization"]} height={108} compact color="#66d9ef" />
        <MetricChart title="TX Utilization" metric={metrics?.metrics["tx.utilization"]} height={108} compact color="#f7c873" />
        <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} height={126} compact color="#66d9ef" />
        <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} height={126} compact color="#f7c873" />
        <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={108} compact color="#7fd4c7" />
        <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={108} compact color="#d8b86d" />
        <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={108} compact color="#d6b66f" />
        <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={108} compact color="#cda866" />
        <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={108} compact color="#d98b7f" />
        <MetricChart title="TX Errors" metric={metrics?.metrics["tx.errors"]} height={108} compact color="#c98278" />
      </section>
    </div>
  );
}

function BandwidthUsagePanel({ item, compact = false }: { item: InterfaceListItem; compact?: boolean }) {
  const rxUsage = item.rxRate?.utilization;
  const txUsage = item.txRate?.utilization;
  const speed = item.link?.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "unknown";
  return (
    <section className={`bandwidth-panel ${compact ? "compact" : ""}`}>
      <div className="bandwidth-panel-header">
        <h3>Link Capacity</h3>
        <span>{speed} / {item.link?.duplex ?? "duplex unknown"} / {item.link?.operstate ?? "state unknown"}</span>
      </div>
      <div className="bandwidth-gauge-grid">
        <BandwidthGauge label="RX" usage={rxUsage} bitrate={item.rxRate?.bitrateBps ?? item.rxBitrate.value ?? item.rxBitrate.avg} headroom={item.rxRate?.headroomBps} color="#66d9ef" />
        <BandwidthGauge label="TX" usage={txUsage} bitrate={item.txRate?.bitrateBps ?? item.txBitrate.value ?? item.txBitrate.avg} headroom={item.txRate?.headroomBps} color="#f7c873" />
      </div>
    </section>
  );
}

function BandwidthGauge({ label, usage, bitrate, headroom, color }: { label: string; usage?: number; bitrate?: number; headroom?: number; color: string }) {
  const clamped = usage === undefined ? undefined : Math.max(0, Math.min(1, usage));
  const dash = clamped === undefined ? 0 : clamped * 100;
  const hasVisibleValue = clamped !== undefined && clamped >= 0.01;
  return (
    <div className="bandwidth-gauge-card" style={{ "--gauge-color": color } as CSSProperties}>
      <svg className={`bandwidth-gauge ${clamped === undefined ? "unknown" : ""}`} viewBox="0 0 100 62" aria-hidden="true">
        <path className="bandwidth-gauge-track" d="M10 52a40 40 0 0 1 80 0" pathLength="100" />
        {hasVisibleValue && <path className="bandwidth-gauge-value" d="M10 52a40 40 0 0 1 80 0" pathLength="100" strokeDasharray={`${dash} ${100 - dash}`} />}
      </svg>
      <div className="bandwidth-gauge-center">
        <strong>{formatPercent(clamped)}</strong>
        <span>{label} used</span>
      </div>
      <div className="bandwidth-gauge-meta">
        <span>{formatBitrate(bitrate)}</span>
        <small>free {formatBitrate(headroom)}</small>
      </div>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>;
}

function interfaceHeadroom(item: InterfaceListItem) {
  const values = [item.rxRate?.utilization, item.txRate?.utilization].filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  return values.length > 0 ? 1 - Math.max(...values) : undefined;
}

function formatPercent(value: number | undefined) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return `${Math.round(Math.max(0, Math.min(1, value)) * 100)}%`;
}

function formatLinkSummary(item: InterfaceListItem) {
  const speed = item.link?.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "speed unknown";
  const duplex = item.link?.duplex ? ` ${item.link.duplex}` : "";
  const state = item.link?.operstate ? ` ${item.link.operstate}` : "";
  return `${speed}${duplex}${state}`;
}

function formatLinkSpeed(speedMbps: number) {
  if (speedMbps < 1000) return `${speedMbps}M`;
  const gbps = speedMbps / 1000;
  return `${Number.isInteger(gbps) ? gbps.toFixed(0) : gbps.toFixed(1)}G`;
}

