      </div>
      <div className="bandwidth-gauge-grid">
        <BandwidthGauge label="RX" usage={rxUsage} bitrate={item.rxRate?.bitrateBps ?? item.rxBitrate.value ?? item.rxBitrate.avg} headroom={item.rxRate?.headroomBps} color="#66d9ef" />
        <BandwidthGauge label="TX" usage={txUsage} bitrate={item.txRate?.bitrateBps ?? item.txBitrate.value ?? item.txBitrate.avg} headroom={item.txRate?.headroomBps} color="#f7c873" />
      </div>
    </section>
  );
}

function BandwidthGauge({ label, usage, bitrate, headroom, color }: { label: string; usage?: number; bitrate?: number; headroom?: number; color: string }) {
  const clamped = usage === undefined ? undefined : Math.max(0, Math.min(1, usage));
  const dash = clamped === undefined ? 0 : clamped * 100;
  const hasVisibleValue = clamped !== undefined && clamped >= 0.01;
  return (
    <div className="bandwidth-gauge-card" style={{ "--gauge-color": color } as CSSProperties}>
      <svg className={`bandwidth-gauge ${clamped === undefined ? "unknown" : ""}`} viewBox="0 0 100 62" aria-hidden="true">
        <path className="bandwidth-gauge-track" d="M10 52a40 40 0 0 1 80 0" pathLength="100" />
        {hasVisibleValue && <path className="bandwidth-gauge-value" d="M10 52a40 40 0 0 1 80 0" pathLength="100" strokeDasharray={`${dash} ${100 - dash}`} />}
      </svg>
      <div className="bandwidth-gauge-center">
        <strong>{formatPercent(clamped)}</strong>
        <span>{label} used</span>
      </div>
      <div className="bandwidth-gauge-meta">
        <span>{formatBitrate(bitrate)}</span>
        <small>free {formatBitrate(headroom)}</small>
      </div>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>;
}

function interfaceHeadroom(item: InterfaceListItem) {
  const values = [item.rxRate?.utilization, item.txRate?.utilization].filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  return values.length > 0 ? 1 - Math.max(...values) : undefined;
}

function formatPercent(value: number | undefined) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return `${Math.round(Math.max(0, Math.min(1, value)) * 100)}%`;
}

function formatLinkSummary(item: InterfaceListItem) {
  const speed = item.link?.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "speed unknown";
  const duplex = item.link?.duplex ? ` ${item.link.duplex}` : "";
  const state = item.link?.operstate ? ` ${item.link.operstate}` : "";
  return `${speed}${duplex}${state}`;
}

function formatLinkSpeed(speedMbps: number) {
  if (speedMbps < 1000) return `${speedMbps}M`;
  const gbps = speedMbps / 1000;
  return `${Number.isInteger(gbps) ? gbps.toFixed(0) : gbps.toFixed(1)}G`;
}

