  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
};

const FLOW_ROLE_ACCENTS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
