import type { FlowMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";
import { MetricChart } from "./MetricChart";

type DetailPaneProps = {
