const FLOW_ROLE_ACCENTS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
  default: "#7f98b5"
};

export function DetailPane({
  stream,
  metrics,
  selectedFlowKey,
  metricsRange,
  onChangeMetricsRange,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls
}: DetailPaneProps) {
  if (!stream) {
    return <aside className="detail-pane empty-state">Select a stream to inspect bitrate and flow metrics.</aside>;
  }

  const descriptors = metrics?.descriptors ?? [];
  const visibleFlows = selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows;
  const visibleMetrics = metrics && selectedFlowKey
    ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) }
    : metrics;
  const primary = descriptors.filter((descriptor) => descriptor.category === "primary");
  const secondary = descriptors.filter((descriptor) => descriptor.category === "secondary");
  const stats = descriptors.filter((descriptor) => descriptor.category === "stat");

  return (
    <aside className={`detail-pane ${mode === "overview" ? "graph-mode" : ""}`}>
      <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <span className="kind-pill">{stream.kind}</span>
          <h2>{stream.label}</h2>
          <p>{selectedFlowKey ? "Filtered to one flow" : `${stream.flowCount} flow${stream.flowCount === 1 ? "" : "s"}`} / last seen {formatRelativeTime(stream.lastSeen)}</p>
        </div>
        <div className="detail-header-actions">
          <label className="detail-range-select">
            <span>Range</span>
            <select value={metricsRange} onChange={(event) => onChangeMetricsRange(event.target.value)}>
              <option value="24h">24h</option>
              <option value="12h">12h</option>
              <option value="6h">6h</option>
              <option value="3h">3h</option>
              <option value="1h">1h</option>
              <option value="30m">30m</option>
              <option value="10m">10m</option>
              <option value="5m">5m</option>
            </select>
          </label>
          <div className="detail-mode-tabs" role="tablist" aria-label="Detail mode">
            <button className={mode === "overview" ? "active" : ""} onClick={() => onChangeMode("overview")} type="button">Overview</button>
            <button className={mode === "detail" ? "active" : ""} onClick={() => onChangeMode("detail")} type="button">Detail</button>
          </div>
          {showWidthControls && (
            <div className="pane-width-controls" aria-label="Detail width controls">
              <button type="button" className={`size-button size-button-v size-button-left ${isWidthMaximized ? "active" : ""}`} onClick={onMaximizeWidth} aria-pressed={isWidthMaximized} title="Maximize detail pane"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-center ${isWidthRestored ? "active" : ""}`} onClick={onRestoreWidth} aria-pressed={isWidthRestored} title="Restore detail pane width"><span className="width-icon" aria-hidden="true" /></button>
              <button type="button" className={`size-button size-button-v size-button-right ${isWidthMinimized ? "active" : ""}`} onClick={onMinimizeWidth} aria-pressed={isWidthMinimized} title="Shrink detail pane"><span className="width-icon" aria-hidden="true" /></button>
            </div>
          )}
        </div>
      </header>

      <div className="detail-body">
        {mode === "overview" ? (
          <GraphMode
            stream={stream}
            metrics={visibleMetrics}
            visibleFlows={visibleFlows}
            descriptors={[...primary, ...secondary]}
            selectedFlowKey={selectedFlowKey}
          />
        ) : (
          <>
            <div className="overview-grid">
              <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
              <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
              <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
            </div>

            <section className="flow-table-card">
              <h3>Flows</h3>
              <div className="flow-table">
                {visibleFlows.map((flow) => (
                  <div className="flow-row" key={flow.flowKey}>
                    <strong>{flow.role}</strong>
                    <span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span>
                    <span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span>
                  </div>
                ))}
              </div>
            </section>

            {stats.length > 0 && <StatsSection descriptors={stats} metrics={visibleMetrics} />}

            {!selectedFlowKey && <MetricChart title="Stream Bitrate" metric={metrics?.streamBitrate} />}

            {primary.map((descriptor) => (
              <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} />
            ))}

            {secondary.length > 0 && (
              <details className="more-metrics">
                <summary>More numeric metrics</summary>
                {secondary.slice(0, 12).map((descriptor) => (
                  <FlowMetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} compact />
                ))}
              </details>
            )}
          </>
        )}
      </div>
    </aside>
  );
}

function GraphMode({
  stream,
  metrics,
  visibleFlows,
  descriptors,
  selectedFlowKey
}: {
  stream: StreamState;
  metrics: StreamMetricsResponse | null;
  visibleFlows: StreamState["flows"];
  descriptors: MetricDescriptor[];
  selectedFlowKey?: string | null;
}) {
  const nonBitrateDescriptors = descriptors
    .filter((descriptor) => descriptor.key !== "bitrate")
    .sort((a, b) => a.priority - b.priority);
  const metricByFlowKey = new Map((metrics?.flows ?? []).map((flow) => [flow.flowKey, flow]));
  const streamBitrate = metrics?.streamBitrate;

  return (
    <div className="graph-mode-layout">
      <section className="graph-summary-band">
        <Stat label="Total Bitrate" value={formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)} />
        <Stat label="Status" value={stream.active ? "Active" : "Stale"} />
        <Stat label="Flows" value={String(visibleFlows.length)} />
        <Stat label="Roles" value={selectedFlowKey ? (visibleFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")} />
      </section>

      {!selectedFlowKey && (
        <section className="graph-hero-card">
          <MetricChart title="Stream Bitrate" metric={streamBitrate} height={96} compact fillHeight color="#66d9ef" />
        </section>
      )}

      <section className={`graph-flow-grid ${visibleFlows.length === 1 ? "single" : ""}`}>
        {visibleFlows.map((flow) => {
          const flowMetrics = metricByFlowKey.get(flow.flowKey);
          const charts = [
            flowMetrics?.metrics.bitrate ? { key: "bitrate", label: "Bitrate", metric: flowMetrics.metrics.bitrate } : null,
            ...nonBitrateDescriptors
              .map((descriptor) => {
                const metric = flowMetrics?.metrics[descriptor.key];
                return metric ? { key: descriptor.key, label: descriptor.label, metric } : null;
              })
              .filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item))
          ].filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item));

          return (
            <GraphFlowCard
              key={flow.flowKey}
              flow={flow}
              metrics={flowMetrics}
              charts={charts}
            />
          );
        })}
      </section>
    </div>
  );
}

function GraphFlowCard({
  flow,
  metrics,
  charts
}: {
  flow: StreamState["flows"][number];
  metrics?: FlowMetricsResponse;
  charts: Array<{ key: string; label: string; metric: TimeSeriesMetric }>;
}) {
  const accent = flowAccent(flow.role);
  const bitrate = metrics?.metrics.bitrate?.points.at(-1)?.avg
    ?? metrics?.metrics.bitrate?.points.at(-1)?.value
    ?? flow.metrics.bitrate?.value
    ?? flow.metrics.bitrate?.avg;

  return (
    <section className="graph-flow-card" style={{ borderTopColor: accent }}>
      <div className="graph-flow-card-header">
        <div>
          <strong>{flow.role}</strong>
          <p>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</p>
        </div>
        <span className="graph-flow-rate">{formatBitrate(bitrate)}</span>
      </div>
      <div className={`graph-card-grid ${charts.length === 1 ? "single" : ""}`}>
        {charts.map((chart) => (
          <MetricChart
            key={`${flow.flowKey}:${chart.key}`}
            title={chart.label}
            metric={chart.metric}
            height={chart.key === "bitrate" ? 64 : 52}
            compact
            fillHeight
            color={chart.key === "bitrate" ? accent : colorForMetric(chart.key)}
          />
        ))}
      </div>
    </section>
  );
}

function FlowMetricGroup({ descriptor, metrics, compact = false }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse | null; compact?: boolean }) {
  const flowMetrics = metrics?.flows
    .map((flow) => ({ flow, metric: flow.metrics[descriptor.key] }))
    .filter((item): item is { flow: NonNullable<typeof metrics>["flows"][number]; metric: TimeSeriesMetric } => Boolean(item.metric));

  if (!flowMetrics || flowMetrics.length === 0) return null;

  return (
    <section className={compact ? "metric-group compact" : "metric-group"}>
      <h3>{descriptor.label}</h3>
      <div className="chart-stack">
        {flowMetrics.map(({ flow, metric }) => (
          <MetricChart key={`${flow.flowKey}:${descriptor.key}`} title={flow.label} metric={metric} height={compact ? 130 : 170} color={colorForMetric(descriptor.key)} />
        ))}
      </div>
    </section>
  );
}

function StatsSection({ descriptors, metrics }: { descriptors: MetricDescriptor[]; metrics: StreamMetricsResponse | null }) {
  const values = metrics?.flows.flatMap((flow) =>
    descriptors.flatMap((descriptor) => {
      const latest = flow.metrics[descriptor.key]?.points.at(-1);
      const value = latest?.value ?? latest?.avg;
      return value === undefined ? [] : [{ key: `${flow.flowKey}:${descriptor.key}`, label: `${flow.role} ${descriptor.label}`, value }];
    })
  ) ?? [];

  if (values.length === 0) return null;
  return (
    <section className="stats-section">
      <h3>Stats</h3>
      <div className="stats-grid">
        {values.slice(0, 18).map((item) => <Stat key={item.key} label={item.label} value={formatNumber(item.value)} />)}
      </div>
    </section>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="stat-card"><span>{label}</span><strong>{value}</strong></div>;
}

function flowAccent(role: string) {
  return FLOW_ROLE_ACCENTS[role] ?? FLOW_ROLE_ACCENTS.default;
}

function colorForMetric(key: string) {
  const palette: Record<string, string> = {
    bitrate: "#66d9ef",
    packet_rate: "#8bd17c",
    jitter: "#d6b66f",
    rtt: "#d98b7f",
    rttvar: "#c58bd6",
    bandwidth: "#7fa7d9",
    rate: "#70c7b0",
    rcvrate: "#9ca4d9",
    interval: "#d69f73",
    clock_skew: "#b5c46f",
    nak_seqno: "#d184a8"
  };
  const root = key.split(".")[0];
  return palette[root] ?? fallbackMetricColor(root);
}

function fallbackMetricColor(key: string) {
  const colors = ["#8fb8d8", "#91c7a3", "#c9b878", "#d09787", "#a995d0", "#78c2bf", "#c99ac0"];
  let hash = 0;
  for (const char of key) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return colors[hash % colors.length];
}
