  const eventsMinimized = eventsHeight <= MINIMIZED_EVENTS_HEIGHT;
  const eventsMaximized = eventsMaxHeight > MINIMIZED_EVENTS_HEIGHT && eventsHeight >= eventsMaxHeight;
  const eventsRestored = !eventsMinimized && !eventsMaximized;
  const rightColumnRows = eventsMaximized
    ? `0px 8px minmax(0, 1fr)`
    : `minmax(0, 1fr) 8px ${Math.max(MINIMIZED_EVENTS_HEIGHT, eventsHeight)}px`;

  const timelineMaxHeight = Math.max(MIN_TIMELINE_HEIGHT, leftColumnHeight - 8);
  const timelineMinimized = timelineHeight <= MIN_TIMELINE_HEIGHT;
  const timelineMaximized = timelineMaxHeight > MIN_TIMELINE_HEIGHT && timelineHeight >= timelineMaxHeight;
  const timelineRestored = !timelineMinimized && !timelineMaximized;
  const leftColumnRows = timelineMaximized
    ? `auto 0px 8px minmax(0, 1fr)`
    : `auto minmax(0, 1fr) 8px ${Math.max(MIN_TIMELINE_HEIGHT, timelineHeight)}px`;

  const wideLayout = workspaceWidth > 1100;
  const minRightWidth = rightPaneWidth <= COLLAPSED_RIGHT_WIDTH ? COLLAPSED_RIGHT_WIDTH : MIN_RIGHT_WIDTH;
  const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
  const rightPaneMaximized = wideLayout && rightPaneWidth >= maxRightWidth;
  const rightPaneMinimized = !wideLayout || rightPaneWidth <= MIN_RIGHT_WIDTH;
  const listOverviewMode = wideLayout && rightPaneWidth <= COLLAPSED_RIGHT_WIDTH;
  const rightPaneRestored = wideLayout && !rightPaneMaximized && !rightPaneMinimized;
  const workspaceColumns = wideLayout
    ? `minmax(0, 1fr) 8px ${Math.min(maxRightWidth, Math.max(minRightWidth, rightPaneWidth))}px`
    : undefined;

  const startResizeEvents = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const startY = event.clientY;
    const startHeight = eventsHeight;
    const columnHeight = event.currentTarget.parentElement?.getBoundingClientRect().height ?? rightColumnHeight;
    setRightColumnHeight(columnHeight);
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.classList.add("is-resizing-pane");
    setResizingPane("height");

    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, columnHeight - 8);
      const next = Math.min(maxHeight, Math.max(MINIMIZED_EVENTS_HEIGHT, startHeight - (moveEvent.clientY - startY)));
      setEventsHeight(next);
      if (next > MINIMIZED_EVENTS_HEIGHT && next < maxHeight) setEventsRestoreHeight(next);
    };
    const onUp = () => {
      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const startResizeTimeline = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const startY = event.clientY;
    const startHeight = timelineHeight;
    const columnHeight = event.currentTarget.parentElement?.getBoundingClientRect().height ?? leftColumnHeight;
    setLeftColumnHeight(columnHeight);
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.classList.add("is-resizing-pane");
    setResizingPane("height");

    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxHeight = Math.max(MIN_TIMELINE_HEIGHT, columnHeight - 8);
      const next = Math.min(maxHeight, Math.max(MIN_TIMELINE_HEIGHT, startHeight - (moveEvent.clientY - startY)));
      setTimelineHeight(next);
      if (next > MIN_TIMELINE_HEIGHT && next < maxHeight) setTimelineRestoreHeight(next);
    };
    const onUp = () => {
