  const liveTone = contextTimeSec !== null || contextPaused ? "warning" as const : "success" as const;
  const toggleTheme = () => setTheme((current) => (current === "light" ? "dark" : "light"));
  const toggleLive = () => dashboardTimeContextActive
    ? dashboardSelectedTimeSec !== null || dashboardPaused ? resumeDashboardLive() : pauseDashboardLive()
