item.stdout:
.events-card {
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
}

.events-card-embedded {
  grid-template-rows: minmax(0, 1fr);
  gap: 0;
  padding: 0;
  border-radius: var(--radius-md);
  overflow: hidden;
}

.events-header {
  min-width: 0;
  margin: 0;
  padding: 0 var(--space-2);
  border-bottom: 1px solid var(--line);
}

.detail-pane {
  padding: 0;
  border-radius: var(--radius-md);
  background: var(--surface);
  box-shadow: none;
}

.detail-pane-embedded {
  grid-template-rows: minmax(0, 1fr);
}

.detail-header {
  min-height: 42px;
  margin: 0;
  padding: 6px var(--space-3);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.detail-heading {
.dashboard-view {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  gap: 0;
  padding: var(--space-3);
  overflow: hidden;
}

.dashboard-toolbar {
  min-height: var(--pane-header-height);
  padding: 0 var(--space-2);
  border-bottom: 0;
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

.dashboard-actions {
  gap: var(--space-1);
}

.dashboard-mode-tabs,
.dashboard-events-tabs {
  flex: 0 0 auto;
}

.dashboard-search {
  width: min(240px, 22vw);
}

.dashboard-pane-body {
  min-height: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  background: var(--bg-subtle);
}

.dashboard-action-button,
.dashboard-drag-handle,
.dashboard-cell-remove {
  min-height: 24px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
}

.dashboard-rgl-shell {
  height: 100%;
  overflow: auto;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: var(--bg-subtle);
}

.dashboard-rgl {
  min-height: 100%;
}

.dashboard-cell {
  border-radius: var(--radius-md);
  background: var(--surface);
  box-shadow: none;
}

.dashboard-rgl-shell.is-viewing .dashboard-cell {
  border-color: color-mix(in srgb, var(--line) 82%, transparent);
}

.dashboard-cell-header {
  min-height: 32px;
  padding: var(--space-1) 6px;
  border-bottom-color: var(--line);
  background: var(--surface-muted);
}

.dashboard-cell-header input,
.dashboard-cell-header select {
  min-height: 24px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  padding: 0 6px;
}

.dashboard-cell-body {
  background: var(--surface);
}

.dashboard-rgl-shell.is-editing .dashboard-cell {
  border-color: var(--accent-border);
}

.dashboard-rgl-shell.is-editing .react-grid-item.react-draggable-dragging .dashboard-cell {
  box-shadow: var(--shadow-md);
}

.dashboard-rgl-shell.is-editing .react-resizable-handle::after {
  border-color: var(--accent);
}

@media (max-width: 720px) {
  .dashboard-toolbar .pane-header-meta,
  .dashboard-toolbar .detail-range-select {
    display: none;
  }

  .dashboard-search {
    width: min(180px, 42vw);
  }
}

/* Compact cells keep their identity outside edit mode without recreating a card within a card. */
