  overflow: hidden;
  border: 1px solid var(--line);
}

.dashboard-cell-header.pane-header {
  min-height: 32px;
  height: 32px;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--surface-muted);
}

.dashboard-cell-body {
  min-height: 0;
  overflow: hidden;
}

.dashboard-cell-body .events-card,
.dashboard-cell-body .detail-pane {
  border-radius: 0;
}

