import { Responsive, useContainerWidth, noCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import type { DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts } from "../types/api";

const fixedGridCompactor: Compactor = {
  ...noCompactor,
  preventCollision: true
};

type DashboardGridProps = {
  dashboard: DashboardLayout;
  editing: boolean;
  renderCell: (cell: DashboardCell) => ReactNode;
  onLayoutsChange: (layouts: DashboardResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function DashboardGrid({
  dashboard,
  editing,
  renderCell,
  onLayoutsChange,
  onUpdateCell,
  onRemoveCell
}: DashboardGridProps) {
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<DashboardBreakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => buildResponsiveCells(dashboard.cells, dashboard.layouts), [dashboard.cells, dashboard.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? dashboard.cells;
  const layouts = useMemo(() => Object.fromEntries(
    (Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]).map((breakpoint) => [
      breakpoint,
      cellsByBreakpoint[breakpoint].map(toLayoutItem)
    ])
  ) as unknown as Record<DashboardBreakpoint, Layout>, [cellsByBreakpoint]);

  const handleLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const normalized = {} as DashboardResponsiveLayouts;
    for (const breakpoint of Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]) {
      const layout = nextLayouts[breakpoint];
      if (layout) normalized[breakpoint] = mergeLayoutCells(cellsByBreakpoint[breakpoint], layout);
    }
    onLayoutsChange(normalized);
  }, [editing, cellsByBreakpoint, onLayoutsChange]);

  return (
    <div ref={containerRef as unknown as Ref<HTMLDivElement>} className={`dashboard-rgl-shell ${editing ? "is-editing" : "is-viewing"}`}>
      {mounted && (
        <Responsive
          className="dashboard-rgl"
          width={width}
          layouts={layouts}
          breakpoints={BREAKPOINTS}
          cols={BREAKPOINT_COLUMNS}
          rowHeight={dashboard.rowHeight}
          margin={[10, 10]}
          containerPadding={[0, 0]}
          dragConfig={{
            enabled: editing,
            handle: ".dashboard-drag-handle",
            cancel: ".dashboard-cell-body, input, select, .dashboard-cell-remove, a"
          }}
          resizeConfig={{
            enabled: editing,
            handles: ["se"]
          }}
          compactor={fixedGridCompactor}
          autoSize
          onBreakpointChange={(breakpoint) => setActiveBreakpoint(toDashboardBreakpoint(breakpoint))}
          onLayoutChange={handleLayoutChange}
        >
          {activeCells.map((cell) => (
            <section key={cell.id} className={`dashboard-cell dashboard-cell-${cell.viewType}`}>
              <header className="pane-header pane-header-compact dashboard-cell-header">
                {editing ? <>
                  <button type="button" className="dashboard-drag-handle" aria-label="Move cell" title="Drag to move">⋮⋮</button>
                  <input
                    value={cell.title}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value }))}
                    aria-label="Cell title"
                  />
                  <select
                    value={cell.viewType}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, viewType: event.target.value as DashboardCell["viewType"], title: titleForDashboardView(event.target.value as DashboardCell["viewType"]) }))}
                    aria-label="Cell view type"
                  >
                    {DASHBOARD_VIEW_TYPES.map((viewType) => <option key={viewType} value={viewType}>{titleForDashboardView(viewType)}</option>)}
                  </select>
                  <button type="button" className="dashboard-cell-remove" onClick={() => onRemoveCell(cell.id)} disabled={activeCells.length <= 1} aria-label="Remove cell">×</button>
                </> : <strong className="pane-header-title">{cell.title}</strong>}
              </header>
              <div className="dashboard-cell-body">
                {renderCell(cell)}
              </div>
            </section>
          ))}
        </Responsive>
      )}
    </div>
  );
}
const BREAKPOINTS: Record<DashboardBreakpoint, number> = { desktop: 1200, tablet: 700, mobile: 0 };
const BREAKPOINT_COLUMNS: Record<DashboardBreakpoint, number> = { desktop: 24, tablet: 12, mobile: 4 };

function breakpointForWidth(width: number): DashboardBreakpoint {
  if (width >= BREAKPOINTS.desktop) return "desktop";
  if (width >= BREAKPOINTS.tablet) return "tablet";
  return "mobile";
}

function toDashboardBreakpoint(breakpoint: string): DashboardBreakpoint {
  return breakpoint === "desktop" || breakpoint === "tablet" || breakpoint === "mobile"
    ? breakpoint
    : "desktop";
}

function toLayoutItem(cell: DashboardCell): LayoutItem {
  return {
    i: cell.id,
    x: cell.grid.x,
    y: cell.grid.y,
    w: cell.grid.w,
    h: cell.grid.h,
    minW: 2,
    maxW: 48,
    minH: 3,
    maxH: 40,
    isBounded: true
  };
}

function buildResponsiveCells(cells: DashboardCell[], saved: DashboardResponsiveLayouts | undefined): Record<DashboardBreakpoint, DashboardCell[]> {
  return {
    desktop: saved?.desktop ?? cells,
    tablet: saved?.tablet ?? fallbackLayout(cells, 12, 2),
    mobile: saved?.mobile ?? fallbackLayout(cells, 4, 1)
  };
}

function fallbackLayout(cells: DashboardCell[], columns: number, columnCount: number) {
  const slotWidth = Math.floor(columns / columnCount);
  const result: DashboardCell[] = [];
  let y = 0;
  for (let index = 0; index < cells.length; index += columnCount) {
    const row = cells.slice(index, index + columnCount);
    const rowHeight = Math.max(...row.map((cell) => cell.grid.h), 3);
    row.forEach((cell, column) => {
      result.push({
        ...cell,
        grid: {
          x: column * slotWidth,
          y,
          w: slotWidth,
          h: cell.grid.h
        }
      });
    });
    y += rowHeight;
  }
  return result;
}

function mergeLayoutCells(cells: DashboardCell[], layout: Layout) {
  const positions = new Map(layout.map((item) => [item.i, item]));
  return cells.map((cell) => {
    const item = positions.get(cell.id);
    return item ? { ...cell, grid: { x: item.x, y: item.y, w: item.w, h: item.h } } : cell;
  });
}

const DASHBOARD_VIEW_TYPES: DashboardCell["viewType"][] = ["streams", "detail", "timeline", "topology", "events"];

function titleForDashboardView(viewType: DashboardCell["viewType"]) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Detail";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}
      layouts: layout.layouts ? Object.fromEntries(
        Object.entries(layout.layouts).map(([breakpoint, cells]) => [breakpoint, cells.filter((cell) => cell.id !== cellId)])
      ) as DashboardResponsiveLayouts : undefined
    }));
  };

  const resetDashboardLayout = () => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => {
      const retained = layouts.filter((layout) => layout.id !== DEFAULT_DASHBOARD_LAYOUT.id);
      return [DEFAULT_DASHBOARD_LAYOUT, ...retained];
    });
    setDashboardLayoutId(DEFAULT_DASHBOARD_LAYOUT.id);
  };

  const saveDashboardLayout = async () => {
    setDashboardSaveState("saving");
    try {
      const saved = await saveDashboardLayouts(dashboardLayouts);
      setDashboardLayouts(saved.length > 0 ? saved : [DEFAULT_DASHBOARD_LAYOUT]);
      setDashboardSaveState("saved");
    } catch {
      setDashboardSaveState("error");
    }
  };

  const updateDashboardLayouts = (nextLayouts: DashboardResponsiveLayouts) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => {
      if (layout.id !== dashboardLayout.id) return layout;
      const desktop = nextLayouts.desktop ?? layout.cells;
      return { ...layout, cells: desktop, layouts: nextLayouts };
    }));
  };

  const dashboardHasDetailCell = dashboardLayout.cells.some((cell) => cell.viewType === "detail");
  const dashboardHasEventsCell = dashboardLayout.cells.some((cell) => cell.viewType === "events");

  const renderDashboardView = () => (
    <section className="main-tab-view dashboard-view">
      <PaneHeader
        className="dashboard-toolbar"
        title="Dashboard"
        meta={dashboardContextLabel + " · " + dashboardLayout.cells.length + " cells / " + dashboardLayout.columns + " columns"}
        actions={<div className="dashboard-actions">
          <SearchInput className="dashboard-search" value={query} onChange={setQuery} placeholder="Filter dashboard" label="dashboard search" />
          <label className="detail-range-select dashboard-time-range">
            <span>Range</span>
            <select value={dashboardRange} onChange={(event) => setDashboardRange(event.target.value)}>
              {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
            </select>
          </label>
          {dashboardHasDetailCell && <div className="detail-mode-tabs dashboard-mode-tabs" role="tablist" aria-label="Detail mode">
            <button type="button" className={detailMode === "overview" ? "active" : ""} onClick={() => setDetailMode("overview")}>Overview</button>
            <button type="button" className={detailMode === "detail" ? "active" : ""} onClick={() => setDetailMode("detail")}>Detail</button>
          </div>}
          {dashboardHasEventsCell && <div className="events-tabs dashboard-events-tabs" role="tablist" aria-label="Event scope">
            <button type="button" className={dashboardEventsTab === "all" ? "active" : ""} onClick={() => setDashboardEventsTab("all")}>All</button>
            <button type="button" className={dashboardEventsTab === "selected" ? "active" : ""} onClick={() => setDashboardEventsTab("selected")}>Selected</button>
          </div>}
          <button type="button" className={"dashboard-action-button" + (!dashboardPaused && dashboardSelectedTimeSec === null ? " primary" : "")} onClick={dashboardSelectedTimeSec !== null || dashboardPaused ? resumeDashboardLive : pauseDashboardLive}>{dashboardSelectedTimeSec !== null || dashboardPaused ? "Live" : "Pause"}</button>
          <label className="detail-range-select">
            <span>Layout</span>
            <select value={dashboardLayout.id} onChange={(event) => setDashboardLayoutId(event.target.value)}>
              {dashboardLayouts.map((layout) => <option key={layout.id} value={layout.id}>{layout.name}</option>)}
            </select>
          </label>
          <button type="button" className={`dashboard-action-button ${dashboardEditing ? "primary" : ""}`} onClick={() => setDashboardEditing((editing) => !editing)}>
            {dashboardEditing ? "Done" : "Edit layout"}
          </button>
          {dashboardEditing && <>
            <button type="button" className="dashboard-action-button" onClick={addDashboardCell}>Add cell</button>
            <button type="button" className="dashboard-action-button" onClick={resetDashboardLayout}>Reset</button>
            <button type="button" className="dashboard-action-button primary" onClick={() => void saveDashboardLayout()} disabled={dashboardSaveState === "saving"}>
              {dashboardSaveState === "saving" ? "Saving" : dashboardSaveState === "saved" ? "Saved" : dashboardSaveState === "error" ? "Retry save" : "Save"}
            </button>
          </>}
        </div>}
      />
      <div className="dashboard-pane-body">
        <DashboardGrid
          dashboard={dashboardLayout}
          editing={dashboardEditing}
          renderCell={(cell) => renderDashboardCellContent(cell.viewType)}
          onLayoutsChange={updateDashboardLayouts}
          onUpdateCell={updateDashboardCell}
          onRemoveCell={removeDashboardCell}
        />
      </div>
    </section>
  );

  const renderDashboardCellContent = (viewType: DashboardViewType) => {
    if (viewType === "streams") {
      return <StreamTable
        streams={filteredStreams}
        interfaces={interfaces}
        selectedStreamKey={selectedStreamKey}
        selectedFlowKey={selectedFlowKey}
        selectedInterfaceKey={selectedInterfaceKey}
        overviewMode
        expandLevel={expandLevel}
        onSelectInterface={(interfaceKey) => {
          setSelectedInterfaceKey(interfaceKey);
          setSelectedStreamKey(null);
          setSelectedFlowKey(null);
        }}
        onSelectStream={(streamKey) => {
          setSelectedInterfaceKey(null);
          setSelectedStreamKey(streamKey);
          setSelectedFlowKey(null);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          setSelectedInterfaceKey(null);
          setSelectedStreamKey(streamKey);
          setSelectedFlowKey(flowKey);
        }}
      />;
    }
    if (viewType === "detail") {
      return selectedInterface && !selectedStreamKey ? <InterfaceDetailPane
        item={selectedInterface}
        metrics={selectedInterfaceMetrics}
        mode={detailMode}
        onChangeMode={setDetailMode}
        onMinimizeWidth={() => undefined}
        onRestoreWidth={() => undefined}
        onMaximizeWidth={() => undefined}
        isWidthMinimized={false}
        isWidthRestored
        isWidthMaximized
        showWidthControls={false}
        embedded
      /> : <DetailPane
        stream={detailStream}
        metrics={selectedMetrics}
        selectedFlowKey={selectedFlowKey}
        metricsRange={dashboardRange}
        onChangeMetricsRange={setDashboardRange}
        mode={detailMode}
        onChangeMode={setDetailMode}
        onMinimizeWidth={() => undefined}
        onRestoreWidth={() => undefined}
        onMaximizeWidth={() => undefined}
        isWidthMinimized={false}
        isWidthRestored
        isWidthMaximized
        showWidthControls={false}
        embedded
      />;
    }
    if (viewType === "timeline") {
      return (
        <div className="timeline-body dashboard-timeline-body">
          <TimelinePane
            rows={filteredTimeline}
            nowSec={dashboardSelectedTimeSec ?? summary.updatedAt ?? Date.now() / 1000}
            fadeSec={appConfig.lostRetentionSec}
            rangeStartSec={timelineWindow.from}
            rangeEndSec={timelineWindow.to}
            expandLevel={timelineExpandLevel}
            selectedTimeSec={dashboardSelectedTimeSec}
            onSelectTime={selectDashboardTime}
            interfaceNames={timelineInterfaceNames}
          />
        </div>
      );
    }
    if (viewType === "topology") return <TopologyPane
      selectedTimeSec={dashboardSelectedTimeSec}
      filterQuery={query}
      onSelectStream={(streamKey) => {
        setSelectedInterfaceKey(null);
        setSelectedStreamKey(streamKey);
        setSelectedFlowKey(null);
      }}
      onSelectFlow={(streamKey, flowKey) => {
        setSelectedInterfaceKey(null);
        setSelectedStreamKey(streamKey);
        setSelectedFlowKey(flowKey);
      }}
      onSelectTime={selectDashboardTime}
    />;
    return <EventLog
      events={events}
      eventsRange={dashboardRange}
      onChangeEventsRange={setDashboardRange}
      query={query}
      onChangeQuery={setQuery}
      showSearch={false}
      showHeader={false}
      tab={dashboardEventsTab}
      onChangeTab={setDashboardEventsTab}
      selectedStreamKey={selectedStreamKey}
      selectedFlowKey={selectedFlowKey}
      selectedInterfaceId={selectedInterface?.interfaceId ?? null}
      selectedTimeSec={dashboardSelectedTimeSec}
      onSelectTime={selectDashboardTime}
    />;
  };

import { useLayoutEffect, useRef, useState } from "react";
import type { EventLogItem } from "../types/api";
import { SearchInput } from "./ui/SearchInput";
import { matchesSearch } from "./search";

const MAX_RENDERED_EVENTS = 8000;

type EventLogProps = {
  events: EventLogItem[];
  eventsRange: string;
  onChangeEventsRange: (value: string) => void;
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceId: number | null;
  initialQuery?: string;
  query?: string;
  onChangeQuery?: (value: string) => void;
  showSearch?: boolean;
  tab?: EventLogTab;
  onChangeTab?: (tab: EventLogTab) => void;
  showHeader?: boolean;
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
};

export type EventLogTab = "all" | "selected";

export function EventLog({
  events,
  eventsRange,
  onChangeEventsRange,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceId,
  initialQuery = "",
  query: controlledQuery,
  onChangeQuery,
  showSearch = true,
  tab: controlledTab,
  onChangeTab,
  showHeader = true,
  selectedTimeSec = null,
  onSelectTime
}: EventLogProps) {
  const [internalTab, setInternalTab] = useState<EventLogTab>("all");
  const [internalQuery, setInternalQuery] = useState(initialQuery);
  const tab = controlledTab ?? internalTab;
  const setTab = onChangeTab ?? setInternalTab;
  const query = controlledQuery ?? internalQuery;
  const setQuery = onChangeQuery ?? setInternalQuery;
  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
  const listRef = useRef<HTMLDivElement | null>(null);
  const scrollSnapshotRef = useRef({ top: 0, height: 0 });
  const followLatestRef = useRef(true);
  const eventRowRefs = useRef(new Map<string, HTMLButtonElement>());
  const lastAutoScrolledKeyRef = useRef<string | null>(null);
  const scopedEvents = tab === "all" ? events : events.filter((event) => {
    if (selectedFlowKey) return event.flowKey === selectedFlowKey || event.streamKey === selectedStreamKey;
    if (selectedStreamKey) return event.streamKey === selectedStreamKey;
    if (selectedInterfaceId !== null) return event.interfaceId === selectedInterfaceId;
    return false;
  });
  const normalizedQuery = query.trim();
  const visibleEvents = normalizedQuery ? scopedEvents.filter((event) => eventMatches(event, query)) : scopedEvents;
  const renderedEvents = visibleEvents.slice(0, MAX_RENDERED_EVENTS);
  const visibleSignature = `${visibleEvents[0]?.id ?? ""}:${visibleEvents.length}:${visibleEvents[visibleEvents.length - 1]?.id ?? ""}`;

  useLayoutEffect(() => {
    const element = listRef.current;
    if (!element || visibleEvents.length === 0) return;
    const prev = scrollSnapshotRef.current;
    const heightDelta = element.scrollHeight - prev.height;
    if (!followLatestRef.current && heightDelta !== 0) element.scrollTop = prev.top + heightDelta;
