  }
}

function timelineFollowRefreshMs(windowSec: number) {
  if (windowSec <= 10 * 60) return TIMELINE_FOLLOW_REFRESH_MS;
  if (windowSec <= 60 * 60) return 10_000;
  if (windowSec <= 6 * 60 * 60) return 30_000;
  return 60_000;
}

function applyStreamPatchFrozen(
  current: StreamListItem[],
  upserts: StreamListItem[],
  removes: string[],
  order: string[]
) {
  const next = new Map(current.map((item) => [item.streamKey, item]));
  for (const key of removes) next.delete(key);
  for (const item of upserts) next.set(item.streamKey, item);

  const currentRank = new Map(current.map((item, idx) => [item.streamKey, idx]));
  const serverRank = new Map(order.map((key, idx) => [key, idx]));

  return [...next.values()].sort((a, b) => {
    const ca = currentRank.get(a.streamKey);
    const cb = currentRank.get(b.streamKey);
    if (ca !== undefined || cb !== undefined) {
      if (ca === undefined) return 1;
      if (cb === undefined) return -1;
      return ca - cb;
    }
    const sa = serverRank.get(a.streamKey) ?? Number.MAX_SAFE_INTEGER;
    const sb = serverRank.get(b.streamKey) ?? Number.MAX_SAFE_INTEGER;
    if (sa !== sb) return sa - sb;
    return a.streamKey.localeCompare(b.streamKey);
  });
}

function applyServerOrder(current: StreamListItem[], order: string[]) {
  const rank = new Map(order.map((key, idx) => [key, idx]));
  return [...current].sort((a, b) => {
    const ra = rank.get(a.streamKey) ?? Number.MAX_SAFE_INTEGER;
    const rb = rank.get(b.streamKey) ?? Number.MAX_SAFE_INTEGER;
    if (ra !== rb) return ra - rb;
    return a.streamKey.localeCompare(b.streamKey);
  });
}

function metricsQueryForRange(range: string, centerTimeSec: number | null = null): MetricsRangeQuery {
  const to = centerTimeSec ?? Date.now() / 1000;
  const preset = rangePreset(range);
  if (!preset || (preset.windowSec <= 300 && centerTimeSec === null)) {
    return { windowSec: 300 };
  }
  const windowSec = preset?.windowSec ?? 300;
  return {
    from: Math.max(0, to - windowSec),
    to,
    resolutionSec: preset?.resolutionSec
  };
}

function rangePreset(range: string) {
