    if (!resumed) return;

    let cancelled = false;
    void Promise.all([
      getBootstrap(),
      selectedStreamKeyRef.current ? getStream(selectedStreamKeyRef.current) : Promise.resolve(null),
      selectedStreamKeyRef.current ? getStreamMetrics(selectedStreamKeyRef.current, metricsQueryForRange(selectedMetricsRange)) : Promise.resolve(null),
      selectedInterfaceKeyRef.current ? getInterfaceMetricsByKey(selectedInterfaceKeyRef.current) : Promise.resolve(null)
    ]).then(([bootstrap, stream, metrics, interfaceMetrics]) => {
      if (cancelled) return;
      setStreams(bootstrap.streams);
      setInterfaces(bootstrap.interfaces);
      setSummary(bootstrap.summary);
      if (!eventsLoadedRef.current) setEvents(bootstrap.events);
      setSelectedStream(stream);
      setSelectedMetrics(metrics);
      setSelectedInterfaceMetrics(interfaceMetrics);
    });

    return () => {
      cancelled = true;
    };
  }, [paused, selectedMetricsRange]);

  const selectedListItem = useMemo(
    () => streams.find((stream) => stream.streamKey === selectedStreamKey) ?? null,
    [streams, selectedStreamKey]
  );

  const selectedInterface = useMemo(
    () => interfaces.find((item) => item.key === selectedInterfaceKey) ?? null,
    [interfaces, selectedInterfaceKey]
  );

  return {
    streams,
    interfaces,
    timeline,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    summary,
    selectedListItem,
    selectedStream,
    selectedMetrics,
    selectedInterface,
    selectedInterfaceMetrics,
    socketState,
    events,
    bootstrapped
