import { useEffect, useMemo, useRef, useState } from "react";
import type { StreamListItem, StreamState } from "./types/api";
import type { Layout } from "react-grid-layout";
import { DashboardGrid } from "./components/DashboardGrid";
import { DetailPane } from "./components/DetailPane";
import { EventLog, type EventLogTab } from "./components/EventLog";
import { AppContextBar } from "./components/ui/AppContextBar";
import { PaneFrame, PaneHeader } from "./components/ui/PaneHeader";
import { SearchInput } from "./components/ui/SearchInput";
import { formatRelativeTime } from "./components/format";
import { InterfaceDetailPane } from "./components/InterfaceDetailPane";
import { StreamTable } from "./components/StreamTable";
import { TimelinePane } from "./components/TimelinePane";
import { TopologyPane } from "./components/TopologyPane";
import { useStreams } from "./hooks/useStreams";
import { getAppConfig, getDashboardLayouts, saveDashboardLayouts } from "./api/client";
import type { AppConfig, DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts, DashboardViewType, TimelineRow } from "./types/api";
import { matchesSearch } from "./components/search";

type ExpandLevel = "interface" | "proto" | "stream" | "flow";
type DetailMode = "overview" | "detail";
type MainTab = "dashboard" | "streams" | "detail" | "timeline" | "topology" | "events";
type MenuItem = {
  key: MainTab;
  icon: string;
  label: string;
  hint: string;
};
type StandaloneView = "streams" | "timeline" | "events" | "detail" | null;

const MENU_ITEMS: MenuItem[] = [
  { key: "dashboard", icon: "◫", label: "Dashboard", hint: "Overview panels" },
  { key: "streams", icon: "≈", label: "Streams", hint: "Tree and filters" },
  { key: "detail", icon: "▤", label: "Detail", hint: "Metrics and flows" },
  { key: "timeline", icon: "▥", label: "Timeline", hint: "History bands" },
  { key: "topology", icon: "◇", label: "Topology", hint: "Network map" },
  { key: "events", icon: "!", label: "Events", hint: "Alerts and logs" }
];
const RANGE_OPTIONS = ["24h", "12h", "6h", "3h", "1h", "30m", "10m", "5m"];
const DEFAULT_DASHBOARD_LAYOUT: DashboardLayout = {
  id: "default",
  name: "Default dashboard",
  columns: 24,
  rowHeight: 32,
  cells: [
    { id: "streams", title: "Streams", viewType: "streams", grid: { x: 0, y: 0, w: 8, h: 11 } },
    { id: "detail", title: "Detail", viewType: "detail", grid: { x: 8, y: 0, w: 8, h: 11 } },
    { id: "topology", title: "Topology", viewType: "topology", grid: { x: 16, y: 0, w: 8, h: 11 } },
    { id: "timeline", title: "Timeline", viewType: "timeline", grid: { x: 0, y: 11, w: 14, h: 8 } },
    { id: "events", title: "Events", viewType: "events", grid: { x: 14, y: 11, w: 10, h: 8 } }
  ]
};


export function App() {
  const initialParams = new URLSearchParams(window.location.search);
  const standaloneView = standaloneViewFromPath(window.location.pathname);
  const [activeTab, setActiveTab] = useState<MainTab>("dashboard");
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    const saved = window.localStorage.getItem("stm-theme");
    return saved === "dark" ? "dark" : "light";
  });
  const [selectedStreamKey, setSelectedStreamKey] = useState<string | null>(() => initialParams.get("streamKey"));
  const [selectedFlowKey, setSelectedFlowKey] = useState<string | null>(() => initialParams.get("flowKey"));
  const [selectedInterfaceKey, setSelectedInterfaceKey] = useState<string | null>(() => initialParams.get("interfaceKey"));
  const [query, setQuery] = useState(() => initialParams.get("query") ?? "");
  const [expandLevel, setExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("expand")));
  const [timelineExpandLevel, setTimelineExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("timelineExpand") ?? initialParams.get("expand")));
  const [detailMode, setDetailMode] = useState<DetailMode>(() => detailModeFromParam(initialParams.get("mode")));
  const [metricsRange, setMetricsRange] = useState(() => rangeFromParam(initialParams.get("metricsRange") ?? initialParams.get("range"), "5m"));
//  const [timelineRange, setTimelineRange] = useState(() => rangeFromParam(initialParams.get("range"), "5m"));
  const [timelineRange, setTimelineRange] = useState(() => rangeFromParam(initialParams.get("range"), "1h"));
  const [eventsRange, setEventsRange] = useState(() => rangeFromParam(initialParams.get("range"), "24h"));
  const [dashboardRange, setDashboardRange] = useState(() => rangeFromParam(initialParams.get("dashboardRange"), "1h"));
  const [dashboardSelectedTimeSec, setDashboardSelectedTimeSec] = useState<number | null>(null);
  const [dashboardPaused, setDashboardPaused] = useState(false);
  const [dashboardPauseTimeSec, setDashboardPauseTimeSec] = useState<number | null>(null);
  const [timelineSortRefreshToken, setTimelineSortRefreshToken] = useState(0);
  const [streamSortRefreshToken, setStreamSortRefreshToken] = useState(0);
  const [timelineFollowNow, setTimelineFollowNow] = useState(true);
  const [manualTimelineWindowEndSec, setManualTimelineWindowEndSec] = useState<number | null>(null);
  const [selectedTimeSec, setSelectedTimeSec] = useState<number | null>(null);
  const [paused, setPaused] = useState(false);
  const [menuExpanded, setMenuExpanded] = useState(false);
  const [appConfigLoaded, setAppConfigLoaded] = useState(false);
  const [appConfig, setAppConfig] = useState<AppConfig>({ lostRetentionSec: 30, historyWindowSec: 300, staleAfterSec: 5 });

  const [dashboardLayouts, setDashboardLayouts] = useState<DashboardLayout[]>([DEFAULT_DASHBOARD_LAYOUT]);
  const [dashboardLayoutId, setDashboardLayoutId] = useState(DEFAULT_DASHBOARD_LAYOUT.id);
  const [dashboardSaveState, setDashboardSaveState] = useState<"idle" | "saving" | "saved" | "error">("idle");
  const [dashboardEditing, setDashboardEditing] = useState(false);

  const MINIMIZED_EVENTS_HEIGHT = 56;
  const DEFAULT_EVENTS_HEIGHT = 240;
  const MIN_TIMELINE_HEIGHT = 64;
  const DEFAULT_TIMELINE_HEIGHT = 180;
  const MIN_RIGHT_WIDTH = 480;
  const COLLAPSED_RIGHT_WIDTH = 56;
  const DEFAULT_RIGHT_WIDTH = 860;

  const [eventsHeight, setEventsHeight] = useState(DEFAULT_EVENTS_HEIGHT);
  const [eventsRestoreHeight, setEventsRestoreHeight] = useState(DEFAULT_EVENTS_HEIGHT);
  const [timelineHeight, setTimelineHeight] = useState(DEFAULT_TIMELINE_HEIGHT);
  const [timelineRestoreHeight, setTimelineRestoreHeight] = useState(DEFAULT_TIMELINE_HEIGHT);
  const [leftColumnHeight, setLeftColumnHeight] = useState(0);
  const [rightColumnHeight, setRightColumnHeight] = useState(0);
  const [workspaceWidth, setWorkspaceWidth] = useState(0);
  const [rightPaneWidth, setRightPaneWidth] = useState(DEFAULT_RIGHT_WIDTH);
  const [rightPaneRestoreWidth, setRightPaneRestoreWidth] = useState(DEFAULT_RIGHT_WIDTH);
  const [resizingPane, setResizingPane] = useState<"height" | "width" | null>(null);

  const leftColumnRef = useRef<HTMLElement | null>(null);
  const rightColumnRef = useRef<HTMLElement | null>(null);
  const workspaceRef = useRef<HTMLElement | null>(null);
  const timelineBodyRef = useRef<HTMLDivElement | null>(null);
  const timelineOrderRef = useRef<{ rank: Map<string, number>; next: number }>({ rank: new Map(), next: 0 });
  const timelineSortAppliedTokenRef = useRef(0);
  const initialSplitAppliedRef = useRef({
    width: false,
    leftHeight: false,
    rightHeight: false
  });

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    window.localStorage.setItem("stm-theme", theme);
  }, [theme]);

  useEffect(() => {
    void getAppConfig()
      .then((config) => setAppConfig(config))
      .catch(() => undefined)
      .finally(() => setAppConfigLoaded(true));
  }, []);

  useEffect(() => {
    void getDashboardLayouts()
      .then((layouts) => {
        const next = layouts.length > 0 ? layouts : [DEFAULT_DASHBOARD_LAYOUT];
        setDashboardLayouts(next);
        setDashboardLayoutId(next[0]?.id ?? DEFAULT_DASHBOARD_LAYOUT.id);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
    if (!leftColumnRef.current) return;
    const element = leftColumnRef.current;
    const updateHeight = () => setLeftColumnHeight(element.getBoundingClientRect().height);
    updateHeight();

    const observer = new ResizeObserver(() => updateHeight());
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!rightColumnRef.current) return;
    const element = rightColumnRef.current;
    const updateHeight = () => setRightColumnHeight(element.getBoundingClientRect().height);
    updateHeight();

    const observer = new ResizeObserver(() => updateHeight());
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!workspaceRef.current) return;
    const element = workspaceRef.current;
    const updateWidth = () => setWorkspaceWidth(element.clientWidth || element.getBoundingClientRect().width);
    updateWidth();

    const observer = new ResizeObserver(() => updateWidth());
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (initialSplitAppliedRef.current.width) return;
    if (workspaceWidth <= 0) return;
    const halfRight = Math.max(MIN_RIGHT_WIDTH, Math.floor((workspaceWidth - 8) / 2));
    setRightPaneWidth(halfRight);
    setRightPaneRestoreWidth(halfRight);
    initialSplitAppliedRef.current.width = true;
  }, [workspaceWidth]);

  useEffect(() => {
    if (initialSplitAppliedRef.current.leftHeight) return;
    if (leftColumnHeight <= 0) return;
    const half = Math.max(MIN_TIMELINE_HEIGHT, Math.floor((leftColumnHeight - 8) / 2));
    setTimelineHeight(half);
    setTimelineRestoreHeight(half);
    initialSplitAppliedRef.current.leftHeight = true;
  }, [leftColumnHeight]);

  useEffect(() => {
    if (initialSplitAppliedRef.current.rightHeight) return;
    if (rightColumnHeight <= 0) return;
    const half = Math.max(MINIMIZED_EVENTS_HEIGHT, Math.floor((rightColumnHeight - 8) / 2));
    setEventsHeight(half);
    setEventsRestoreHeight(half);
    initialSplitAppliedRef.current.rightHeight = true;
  }, [rightColumnHeight]);

  useEffect(() => {
    const maxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, rightColumnHeight - 8);
    setEventsHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
    setEventsRestoreHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
  }, [rightColumnHeight]);

  useEffect(() => {
    const maxHeight = Math.max(MIN_TIMELINE_HEIGHT, leftColumnHeight - 8);
    setTimelineHeight((current) => Math.min(Math.max(current, MIN_TIMELINE_HEIGHT), maxHeight));
    setTimelineRestoreHeight((current) => Math.min(Math.max(current, MIN_TIMELINE_HEIGHT), maxHeight));
  }, [leftColumnHeight]);

  useEffect(() => {
    const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
    setRightPaneWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
    setRightPaneRestoreWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
  }, [workspaceWidth]);

  const dashboardTimeContextActive = !standaloneView && activeTab === "dashboard";
  const activeMetricsRange = dashboardTimeContextActive ? dashboardRange : metricsRange;
  const activeTimelineRange = dashboardTimeContextActive ? dashboardRange : timelineRange;
  const activeEventsRange = dashboardTimeContextActive ? dashboardRange : eventsRange;
  const activeSelectedTimeSec = dashboardTimeContextActive ? dashboardSelectedTimeSec : selectedTimeSec;
  const activePaused = dashboardTimeContextActive ? dashboardPaused || dashboardSelectedTimeSec !== null : paused;
  const activeTimelineFollowNow = dashboardTimeContextActive ? !dashboardPaused && dashboardSelectedTimeSec === null : timelineFollowNow;
  const activeManualTimelineWindowEndSec = dashboardTimeContextActive ? dashboardSelectedTimeSec ?? dashboardPauseTimeSec : manualTimelineWindowEndSec;

  const {
    streams,
    interfaces,
    timeline,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    summary,
    selectedListItem,
    selectedStream,
    selectedMetrics,
    selectedInterface,
    selectedInterfaceMetrics,
    socketState,
    events,
    bootstrapped
  } = useStreams(
    selectedStreamKey,
    selectedInterfaceKey,
    activePaused,
    activeMetricsRange,
    activeTimelineRange,
    activeEventsRange,
    activeTimelineFollowNow,
    activeManualTimelineWindowEndSec,
    streamSortRefreshToken,
    activeSelectedTimeSec,
    setSelectedStreamKey
  );
  const loading = !appConfigLoaded || !bootstrapped;
  const timelineInterfaceNames = useMemo(() => {
    const names = new Map<number, string>();
    for (const item of interfaces) {
      if (item.interfaceId !== undefined) names.set(item.interfaceId, item.name);
    }
    return names;
  }, [interfaces]);

  const filteredStreams = useMemo(() => filterStreams(streams, query), [streams, query]);

  const filteredTimeline = useMemo(() => {
    const normalized = query.trim().toLowerCase();

    const candidateRows = normalized
      ? (() => {
          const visible = timeline.filter((row) =>
            matchesSearch([row.kind, row.label, row.streamKey, row.flowKey, row.interfaceName, row.role, row.endpointSrc, row.endpointDst], query)
          );
          const visibleKeys = new Set(visible.map(timelineRowKey));
          const parentKeys = new Set(
            visible
              .filter((row) => row.rowType === "flow")
              .map((row) => row.parentStreamKey)
              .filter((value): value is string => Boolean(value))
          );
          return timeline.filter((row) => visibleKeys.has(timelineRowKey(row)) || (row.rowType === "stream" && parentKeys.has(row.streamKey)));
        })()
      : timeline;

    if (timelineSortRefreshToken !== timelineSortAppliedTokenRef.current) {
      const streamOrder = new Map(filteredStreams.map((stream, index) => [stream.streamKey, index]));
      const sorted = [...candidateRows].sort((a, b) => compareTimelineRows(a, b, streamOrder));
      const rank = new Map<string, number>();
      sorted.forEach((row, index) => rank.set(timelineRowKey(row), index));
      timelineOrderRef.current = { rank, next: sorted.length };
      timelineSortAppliedTokenRef.current = timelineSortRefreshToken;
      return sorted;
    }

    return candidateRows;
  }, [filteredStreams, timeline, query, timelineSortRefreshToken]);

  const timelineWindowSec = timelineRangeWindowSec(activeTimelineRange);
  const timelineBrowseSpan = Math.max(timelineWindowSec, timelineAvailable.to - timelineAvailable.from);
  const timelineScrollbarMax = Math.max(0, timelineBrowseSpan - timelineWindowSec);
  const timelineScrollbarValue = Math.max(0, timelineWindow.from - timelineAvailable.from);
  const enableTimelineBrowse = timelineScrollbarMax > 0;
  const timelineWheelStepSec = Math.max(1, Math.round(timelineWindowSec * 0.05));

  useEffect(() => {
    const node = timelineBodyRef.current;
    if (!node) return;

    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey || !enableTimelineBrowse) return;
      event.preventDefault();
      const direction = event.deltaY === 0 ? 0 : event.deltaY > 0 ? 1 : -1;
      if (direction === 0) return;
      setTimelineFollowNow(false);
      setManualTimelineWindowEndSec(timelineWindow.to + direction * timelineWheelStepSec);
    };

    node.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      node.removeEventListener("wheel", onWheel);
    };
  }, [enableTimelineBrowse, timelineWindow.to, timelineWheelStepSec]);

