function timelineBounds(rows: TimelineRow[]) {
  if (rows.length === 0) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  let from = Number.POSITIVE_INFINITY;
  let to = Number.NEGATIVE_INFINITY;
  for (const row of rows) {
    from = Math.min(from, row.firstSeen, ...row.segments.map((segment) => segment.start));
    to = Math.max(to, row.lastSeen, ...row.segments.map((segment) => segment.end ?? row.lastSeen));
  }

  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  return { from, to };
}

import { createReadStream, existsSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { descriptorForMetric, normalizeInterfacesLine, normalizeMetricsLine, type NormalizedInterfaceInput, type NormalizedMetricInput } from "../normalizer";
import { config } from "../config";
import type { InterfaceMetricsResponse, MetricDescriptor, MetricPoint, NumericStat, StreamMetricsResponse, TimeSeriesMetric } from "../types";

type AnyRecord = Record<string, any>;

type QueryOptions = {
  streamKey: string;
  from: number;
  to: number;
  resolutionSec?: number;
};

type FlowSeries = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export async function queryMetricsSnapshotAt(time: number): Promise<{ interfaces: NormalizedInterfaceInput[]; metrics: NormalizedMetricInput[] } | undefined> {
  let latestTime = Number.NEGATIVE_INFINITY;
  let latestLine: string | undefined;
  for (const file of listHistoryFiles("raw", Math.max(0, time - 3600), time)) {
    const rl = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      try {
        const parsed = JSON.parse(line) as AnyRecord;
        const entryTime = Number(parsed.time ?? 0);
        if (Number.isFinite(entryTime) && entryTime <= time && entryTime >= latestTime) {
          latestTime = entryTime;
          latestLine = line;
        }
      } catch {
        // Skip partial or malformed JSONL records.
      }
    }
  }
  if (!latestLine) return undefined;
  return { interfaces: normalizeInterfacesLine(latestLine), metrics: normalizeMetricsLine(latestLine) };
}

export async function queryInterfaceMetricsHistory(options: { key: string; from: number; to: number }): Promise<InterfaceMetricsResponse | undefined> {
  const points: Array<{ time: number; metrics: Record<string, NumericStat> }> = [];
  let latest: NormalizedInterfaceInput | undefined;
  for (const file of listHistoryFiles("raw", options.from, options.to)) {
    const rl = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      let items: NormalizedInterfaceInput[];
      try { items = normalizeInterfacesLine(line); } catch { continue; }
      const item = items.find((candidate) => candidate.key === options.key);
      if (!item) continue;
      latest = item;
      points.push({ time: item.lastSeen ?? 0, metrics: interfaceMetrics(item) });
    }
  }
  if (!latest) return undefined;
  return {
    key: latest.key,
    interfaceId: latest.interfaceId,
    name: latest.name,
    windowSec: Math.max(1, options.to - options.from),
    metrics: buildMetricSeries(points)
  };
}

export async function queryStreamMetricsHistory(options: QueryOptions): Promise<StreamMetricsResponse> {
  const source = selectSource(options);
  const files = listHistoryFiles(source, options.from, options.to);
  const flows = new Map<string, FlowSeries>();
  const metricKeys = new Set<string>();

  for (const file of files) {
    await readHistoryFile(file, (entryTime, entry) => {
      if (entryTime < options.from || entryTime > options.to) return;
      if (String(entry?.stream_key ?? "") !== options.streamKey) return;
      const flowKey = typeof entry?.flow_key === "string" ? entry.flow_key : undefined;
      if (!flowKey) return;

      const flow = ensureFlowSeries(flows, flowKey, entry);
      const metrics = extractMetrics(entry);
      for (const [metricKey, stat] of Object.entries(metrics)) {
        metricKeys.add(metricKey);
        flow.metrics[metricKey] ??= {
          key: metricKey,
          label: descriptorForMetric(metricKey).label,
          unit: descriptorForMetric(metricKey).unit,
          points: []
        };
        flow.metrics[metricKey].points.push({
          time: entryTime,
          ...stat
        });

