      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const contextTimeSec = dashboardTimeContextActive ? dashboardSelectedTimeSec : selectedTimeSec;
  const contextPaused = dashboardTimeContextActive ? dashboardPaused : paused;
  const contextUpdatedLabel = `Updated ${summary.updatedAt ? formatRelativeTime(summary.updatedAt) : "waiting"}${contextTimeSec !== null ? ` · ${formatTimeTravel(contextTimeSec)}` : contextPaused ? " · display frozen" : ""}`;
  const liveLabel = contextTimeSec !== null ? "Time travel" : contextPaused ? "Paused" : "Live";
  const liveTone = contextTimeSec !== null || contextPaused ? "warning" as const : "success" as const;
  const toggleTheme = () => setTheme((current) => (current === "light" ? "dark" : "light"));
  const toggleLive = () => dashboardTimeContextActive
    ? dashboardSelectedTimeSec !== null || dashboardPaused ? resumeDashboardLive() : pauseDashboardLive()
    : selectedTimeSec !== null ? resumeLiveTime() : setPaused((current) => !current);

  const renderStatusHeader = (title: string) => (
    <AppContextBar
      compact
      title={title}
      updatedLabel={contextUpdatedLabel}
      socketState={socketState}
      liveLabel={liveLabel}
      liveTone={liveTone}
      onToggleLive={toggleLive}
      onToggleTheme={toggleTheme}
      theme={theme}
    />
  );

  const renderStandaloneSearch = (placeholder: string) => (
    <SearchInput className="standalone-search" value={query} onChange={setQuery} placeholder={placeholder} label="search" />
  );

  const selectGlobalTime = (timeSec: number) => {
    setSelectedTimeSec(timeSec);
    setPaused(true);
    setTimelineFollowNow(false);
    setManualTimelineWindowEndSec(timeSec);
  };

  const resumeLiveTime = () => {
    setSelectedTimeSec(null);
    setPaused(false);
    setTimelineFollowNow(true);
    setManualTimelineWindowEndSec(null);
  };

  const selectDashboardTime = (timeSec: number) => {
    setDashboardSelectedTimeSec(timeSec);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
  };
  const pauseDashboardLive = () => {
    setDashboardPaused(true);
    setDashboardPauseTimeSec(summary.updatedAt ?? Date.now() / 1000);
  };
  const resumeDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
  };

  const dashboardLayout = dashboardLayouts.find((layout) => layout.id === dashboardLayoutId) ?? dashboardLayouts[0] ?? DEFAULT_DASHBOARD_LAYOUT;
  const dashboardContextLabel = dashboardSelectedTimeSec !== null ? formatTimeTravel(dashboardSelectedTimeSec) : dashboardPaused ? "Paused" : "Live";

  const updateDashboardCell = (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => layout.id !== dashboardLayout.id ? layout : {
      ...layout,
      cells: layout.cells.map((cell) => cell.id === cellId ? clampDashboardCell(updater(cell), layout.columns) : cell),
      layouts: layout.layouts ? Object.fromEntries(
        (Object.entries(layout.layouts) as [DashboardBreakpoint, DashboardCell[]][]).map(([breakpoint, cells]) => [
          breakpoint,
          cells.map((cell) => cell.id === cellId ? updater(cell) : cell)
        ])
      ) as DashboardResponsiveLayouts : undefined
    }));
      limit: Number.isFinite(limit) ? limit : undefined
    });
    if (config.diagnosticLog) console.error("[STM_DIAG] api events live result=" + result.length + " journal=" + config.eventJournalDir);
    return result;
  });

  app.get<{ Params: { streamKey: string } }>("/api/streams/:streamKey", async (request, reply) => {
    const stream = store.getStream(decodeURIComponent(request.params.streamKey));
    if (!stream) return reply.code(404).send({ error: "stream not found" });
    return stream;
  });

  app.get<{ Params: { streamKey: string }; Querystring: { windowSec?: string; from?: string; to?: string; resolutionSec?: string } }>(
    "/api/streams/:streamKey/metrics",
    async (request, reply) => {
      const streamKey = decodeURIComponent(request.params.streamKey);
      const from = request.query.from ? Number(request.query.from) : undefined;
      const to = request.query.to ? Number(request.query.to) : undefined;
      const resolutionSec = request.query.resolutionSec ? Number(request.query.resolutionSec) : undefined;
      if (Number.isFinite(from) && Number.isFinite(to) && to! > from!) {
        return queryStreamMetricsHistory({
          streamKey,
          from: from!,
          to: to!,
          resolutionSec: Number.isFinite(resolutionSec) ? resolutionSec : undefined
        });
      }
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      const metrics = store.getMetrics(streamKey, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "stream not found" });
      return metrics;
    }
  );
}

function timelineBounds(rows: TimelineRow[]) {
  if (rows.length === 0) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  let from = Number.POSITIVE_INFINITY;
  let to = Number.NEGATIVE_INFINITY;
  for (const row of rows) {
    from = Math.min(from, row.firstSeen, ...row.segments.map((segment) => segment.start));
    to = Math.max(to, row.lastSeen, ...row.segments.map((segment) => segment.end ?? row.lastSeen));
  }

  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) {
    const now = Date.now() / 1000;
    return { from: now - 300, to: now };
  }

  return { from, to };
}

import { createReadStream, existsSync } from "node:fs";
import path from "node:path";
import readline from "node:readline";
import { descriptorForMetric, normalizeInterfacesLine, normalizeMetricsLine, type NormalizedInterfaceInput, type NormalizedMetricInput } from "../normalizer";
import { config } from "../config";
import type { InterfaceMetricsResponse, MetricDescriptor, MetricPoint, NumericStat, StreamMetricsResponse, TimeSeriesMetric } from "../types";

type AnyRecord = Record<string, any>;

type QueryOptions = {
  streamKey: string;
  from: number;
  to: number;
  resolutionSec?: number;
};

type FlowSeries = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export async function queryMetricsSnapshotAt(time: number): Promise<{ interfaces: NormalizedInterfaceInput[]; metrics: NormalizedMetricInput[] } | undefined> {
  let latestTime = Number.NEGATIVE_INFINITY;
  let latestLine: string | undefined;
  for (const file of listHistoryFiles("raw", Math.max(0, time - 3600), time)) {
    const rl = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      try {
        const parsed = JSON.parse(line) as AnyRecord;
        const entryTime = Number(parsed.time ?? 0);
        if (Number.isFinite(entryTime) && entryTime <= time && entryTime >= latestTime) {
          latestTime = entryTime;
          latestLine = line;
        }
      } catch {
        // Skip partial or malformed JSONL records.
      }
    }
  }
  if (!latestLine) return undefined;
  return { interfaces: normalizeInterfacesLine(latestLine), metrics: normalizeMetricsLine(latestLine) };
}

export async function queryInterfaceMetricsHistory(options: { key: string; from: number; to: number }): Promise<InterfaceMetricsResponse | undefined> {
  const points: Array<{ time: number; metrics: Record<string, NumericStat> }> = [];
  let latest: NormalizedInterfaceInput | undefined;
  for (const file of listHistoryFiles("raw", options.from, options.to)) {
    const rl = readline.createInterface({ input: createReadStream(file), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      let items: NormalizedInterfaceInput[];
      try { items = normalizeInterfacesLine(line); } catch { continue; }
      const item = items.find((candidate) => candidate.key === options.key);
      if (!item) continue;
      latest = item;
      points.push({ time: item.lastSeen ?? 0, metrics: interfaceMetrics(item) });
    }
  }
  if (!latest) return undefined;
  return {
    key: latest.key,
    interfaceId: latest.interfaceId,
    name: latest.name,
    windowSec: Math.max(1, options.to - options.from),
    metrics: buildMetricSeries(points)
  };
}

export async function queryStreamMetricsHistory(options: QueryOptions): Promise<StreamMetricsResponse> {
  const source = selectSource(options);
  const files = listHistoryFiles(source, options.from, options.to);
  const flows = new Map<string, FlowSeries>();
  const metricKeys = new Set<string>();

  for (const file of files) {
    await readHistoryFile(file, (entryTime, entry) => {
      if (entryTime < options.from || entryTime > options.to) return;
      if (String(entry?.stream_key ?? "") !== options.streamKey) return;
      const flowKey = typeof entry?.flow_key === "string" ? entry.flow_key : undefined;
      if (!flowKey) return;

      const flow = ensureFlowSeries(flows, flowKey, entry);
      const metrics = extractMetrics(entry);
      for (const [metricKey, stat] of Object.entries(metrics)) {
        metricKeys.add(metricKey);
        flow.metrics[metricKey] ??= {
          key: metricKey,
          label: descriptorForMetric(metricKey).label,
          unit: descriptorForMetric(metricKey).unit,
          points: []
        };
        flow.metrics[metricKey].points.push({
          time: entryTime,
          ...stat
        });

