import { useEffect, useMemo, useRef, useState } from "react";
import { getBootstrap, getEvents, getInterfaceMetricsByKey, getStream, getStreamMetrics, getStreamsSnapshotAt, getTimeline } from "../api/client";
import type { MetricsRangeQuery } from "../api/client";
import type { EventLogItem, InterfaceListItem, InterfaceMetricsResponse, StreamListItem, StreamMetricsResponse, StreamState, Summary, TimelineRow, TimelineWindow, WsMessage } from "../types/api";

const TIMELINE_QUERY_CHUNK_SEC = 30 * 60;
const TIMELINE_FOLLOW_REFRESH_MS = 5000;
const TIMELINE_DELTA_LOOKBACK_SEC = 120;
const STREAMS_PATCH_APPLY_MS = 2000;
const ENABLE_STREAMS_FULL_UPDATE = false;
const MAX_EVENTS_IN_MEMORY = 8000;

const limitEvents = (items: EventLogItem[]) => items.slice(0, MAX_EVENTS_IN_MEMORY);

export function useStreams(
  selectedStreamKey: string | null,
  selectedInterfaceKey: string | null,
  paused: boolean,
  selectedMetricsRange: string,
  selectedTimelineRange: string,
  selectedEventsRange: string,
  timelineFollowNow: boolean,
  manualTimelineWindowEndSec: number | null,
  streamSortRefreshToken: number,
  selectedTimeSec: number | null,
  onDefaultSelect?: (streamKey: string) => void
) {
  const [streams, setStreams] = useState<StreamListItem[]>([]);
  const [interfaces, setInterfaces] = useState<InterfaceListItem[]>([]);
  const [summary, setSummary] = useState<Summary>({ totalStreams: 0, activeStreams: 0, byKind: {} });
  const [timeline, setTimeline] = useState<TimelineRow[]>([]);
  const [timelineLoading, setTimelineLoading] = useState(false);
  const [timelineWindow, setTimelineWindow] = useState<TimelineWindow>({ from: Date.now() / 1000 - 300, to: Date.now() / 1000 });
  const [timelineAvailable, setTimelineAvailable] = useState<TimelineWindow>({ from: Date.now() / 1000 - 300, to: Date.now() / 1000 });
  const [timelineSource, setTimelineSource] = useState<"live" | "history">("history");
  const [selectedStream, setSelectedStream] = useState<StreamState | null>(null);
  const [selectedMetrics, setSelectedMetrics] = useState<StreamMetricsResponse | null>(null);
  const [selectedInterfaceMetrics, setSelectedInterfaceMetrics] = useState<InterfaceMetricsResponse | null>(null);
  const [socketState, setSocketState] = useState("connecting");
  const [events, setEvents] = useState<EventLogItem[]>([]);
  const [bootstrapped, setBootstrapped] = useState(false);
  const eventsLoadedRef = useRef(false);
  const socketRef = useRef<WebSocket | null>(null);
  const selectedStreamKeyRef = useRef<string | null>(selectedStreamKey);
  const selectedInterfaceKeyRef = useRef<string | null>(selectedInterfaceKey);
  const selectedMetricsRangeRef = useRef(selectedMetricsRange);
  const selectedTimelineRangeRef = useRef(selectedTimelineRange);
  const selectedTimeSecRef = useRef<number | null>(selectedTimeSec);
  const pausedRef = useRef(paused);
  const reconnectTimerRef = useRef<number | null>(null);
  const previousPausedRef = useRef(paused);
  const streamSeqRef = useRef(0);
  const latestServerOrderRef = useRef<string[]>([]);
  const timelineHistoryCacheRef = useRef<{
    from: number;
    to: number;
    rows: TimelineRow[];
    available: TimelineWindow;
    source: "history" | "live";
  } | null>(null);
  const timelineLoadingRef = useRef(false);
  const patchBufferRef = useRef<{
    upserts: StreamListItem[];
    removes: string[];
    order: string[];
    interfaces: InterfaceListItem[];
    summary: Summary;
  } | null>(null);
  const patchTimerRef = useRef<number | null>(null);

  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  useEffect(() => {
    selectedTimeSecRef.current = selectedTimeSec;
  }, [selectedTimeSec]);

  useEffect(() => {
    selectedMetricsRangeRef.current = selectedMetricsRange;
  }, [selectedMetricsRange]);

  useEffect(() => {
    selectedTimelineRangeRef.current = selectedTimelineRange;
  }, [selectedTimelineRange]);

  useEffect(() => {
    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    let loadSeq = 0;
    let initialized = false;
    let backfillTaskSeq = 0;
    const fullLoad = () => {
      loadSeq += 1;
      const seq = loadSeq;
      const liveNowSec = Date.now() / 1000;
      const rangeSec = eventsRangeWindowSec(selectedEventsRange);
      const requestedTo = selectedTimeSec !== null
        ? Math.min(liveNowSec, selectedTimeSec + rangeSec / 2)
        : liveNowSec;
      const from = Math.max(0, requestedTo - rangeSec);
      const to = requestedTo;
      const isLongRange = rangeSec > 3600;

      if (!isLongRange) {
        backfillTaskSeq += 1;
        void getEvents({
          from,
          to,
          limit: 10000
        }).then((items) => {
          if (cancelled || seq !== loadSeq) return;
          eventsLoadedRef.current = true;
          setEvents(limitEvents(items));
        });
        return;
      }

      backfillTaskSeq += 1;
      const currentBackfillSeq = backfillTaskSeq;
      const backfillFrom = from;
      let backfillCursorTo = Math.max(from, to - 3600);
      void getEvents({
        from: Math.max(from, to - 3600),
        to,
        limit: 10000
      }).then((recent) => {
        if (cancelled || seq !== loadSeq) return;
        eventsLoadedRef.current = true;
        setEvents(limitEvents(recent.sort((a, b) => b.time - a.time)));
        const runBackfill = async () => {
          while (!cancelled && seq === loadSeq && currentBackfillSeq === backfillTaskSeq && backfillCursorTo > backfillFrom) {
            const chunkTo = backfillCursorTo;
            const chunkFrom = Math.max(backfillFrom, chunkTo - 3600);
            backfillCursorTo = chunkFrom;
            const chunk = await getEvents({
              from: chunkFrom,
              to: chunkTo,
              limit: 10000
            });
            if (cancelled || seq !== loadSeq || currentBackfillSeq !== backfillTaskSeq) return;
            setEvents((current) => {
              const merged = new Map<string, EventLogItem>();
              for (const item of current) merged.set(item.id, item);
              for (const item of chunk) merged.set(item.id, item);
              return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
            });
          }
        };
        void runBackfill();
      });
    };

    const refreshIncremental = () => {
      const nowSec = selectedTimeSec ?? Date.now() / 1000;
      const rangeSec = eventsRangeWindowSec(selectedEventsRange);
      const deltaFrom = Math.max(0, nowSec - Math.min(rangeSec, 120));
      void getEvents({
        from: deltaFrom,
        to: nowSec,
        limit: 10000
      }).then((chunk) => {
        if (cancelled) return;
        eventsLoadedRef.current = true;
        setEvents((current) => {
          const merged = new Map<string, EventLogItem>();
          const cutoff = nowSec - rangeSec;
          for (const item of current) {
            if (item.time >= cutoff) merged.set(item.id, item);
          }
          for (const item of chunk) {
            if (item.time >= cutoff) merged.set(item.id, item);
          }
          return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
        });
      });
    };

    const load = () => {
      if (!initialized) {
      if (!initialized) {
        initialized = true;
        fullLoad();
        return;
      }
      refreshIncremental();
    };

    load();
    const timer = selectedTimeSec === null ? window.setInterval(load, selectedEventsRange === "24h" ? 15000 : 5000) : undefined;
    return () => {
      cancelled = true;
      loadSeq += 1;
      backfillTaskSeq += 1;
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedEventsRange, selectedTimeSec, paused]);

  useEffect(() => {
    selectedInterfaceKeyRef.current = selectedInterfaceKey;
  }, [selectedInterfaceKey, selectedMetricsRange, selectedTimeSec]);

  useEffect(() => {
    void getBootstrap()
      .then((bootstrap) => {
        setStreams(bootstrap.streams);
        setInterfaces(bootstrap.interfaces);
        setSummary(bootstrap.summary);
        if (!eventsLoadedRef.current) setEvents(bootstrap.events);
        setBootstrapped(true);
        if (!selectedStreamKey && bootstrap.streams.length > 0) onDefaultSelect?.(bootstrap.streams[0].streamKey);
        latestServerOrderRef.current = bootstrap.streams.map((item) => item.streamKey);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
    setStreams((current) => applyServerOrder(current, latestServerOrderRef.current));
  }, [streamSortRefreshToken]);

  useEffect(() => {
    if (selectedTimeSec === null) return;
    let cancelled = false;
    void getStreamsSnapshotAt(selectedTimeSec).then((snapshot) => {
      if (cancelled) return;
      setStreams(snapshot.streams);
      setInterfaces(snapshot.interfaces);
      latestServerOrderRef.current = snapshot.streams.map((item) => item.streamKey);
      const selected = selectedStreamKey
        ? snapshot.streams.find((stream) => stream.streamKey === selectedStreamKey) ?? null
        : null;
      setSelectedStream(selected ? listItemToStreamState(selected) : null);
    }).catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, [selectedTimeSec, selectedStreamKey]);


  useEffect(() => {
    selectedStreamKeyRef.current = selectedStreamKey;
    if (!selectedStreamKey) {
      setSelectedStream(null);
      setSelectedMetrics(null);
      return;
    }
    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    const load = () => {
      if (selectedTimeSec !== null) {
        void getStreamMetrics(selectedStreamKey, metricsQueryForRange(selectedMetricsRange, selectedTimeSec)).then((metrics) => {
          if (!cancelled) setSelectedMetrics(metrics);
        });
        return;
      }
      void Promise.all([getStream(selectedStreamKey), getStreamMetrics(selectedStreamKey, metricsQueryForRange(selectedMetricsRange))]).then(([stream, metrics]) => {
        if (cancelled) return;
        setSelectedStream(stream);
        setSelectedMetrics(metrics);
      });
    };
    load();
    if (selectedMetricsRange === "5m" || selectedTimeSec !== null) {
      return () => {
        cancelled = true;
      };
    }
    const timer = window.setInterval(load, 10000);
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedStreamKey, selectedMetricsRange, selectedTimeSec, paused]);

  useEffect(() => {
    if (selectedInterfaceKey === null) {
      setSelectedInterfaceMetrics(null);
      return;
    }

    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    const load = () => {
      const query = metricsQueryForRange(selectedMetricsRange, selectedTimeSec);
      void getInterfaceMetricsByKey(selectedInterfaceKey, query).then((metrics) => {
        if (!cancelled) setSelectedInterfaceMetrics(metrics);
      }).catch(() => {
        if (!cancelled) setSelectedInterfaceMetrics(null);
      });
    };
    load();
    const timer = selectedTimeSec === null ? window.setInterval(load, 1000) : undefined;
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedInterfaceKey, selectedMetricsRange, selectedTimeSec, paused]);

  useEffect(() => {
    const preset = timelineRangePreset(selectedTimelineRange);
    let cancelled = false;
    const load = (background = false) => {
      if (timelineLoadingRef.current) return;
      timelineLoadingRef.current = true;
      if (!background) setTimelineLoading(true);
      const nowSec = Date.now() / 1000;
      const safeNow = nowSec;
      const desiredToRaw = selectedTimeSec !== null
        ? selectedTimeSec + preset.windowSec / 2
        : timelineFollowNow ? safeNow : manualTimelineWindowEndSec ?? safeNow;
      const desiredTo = Math.min(desiredToRaw, safeNow);
      const cache = timelineHistoryCacheRef.current;
      if (cache) {
        const cachedWindow = clampTimelineWindow({
          desiredTo,
          windowSec: preset.windowSec,
          available: cache.available,
          nowSec: safeNow
        });
        if (cachedWindow.from >= cache.from && cachedWindow.to <= cache.to) {
          setTimeline(clipTimelineRows(cache.rows, cachedWindow.from, cachedWindow.to));
          setTimelineWindow(cachedWindow);
          setTimelineAvailable(cache.available);
          setTimelineSource(cache.source);
          timelineLoadingRef.current = false;
          if (!background) setTimelineLoading(false);
          return;
        }
      }

      const desiredFrom = Math.max(0, desiredTo - preset.windowSec);
      const canServeWindowFromCache =
        cache ? desiredFrom >= cache.from && desiredTo <= cache.to : false;

      if (timelineFollowNow && cache && desiredTo > cache.to && canServeWindowFromCache) {
        const deltaFrom = Math.max(0, cache.to - TIMELINE_DELTA_LOOKBACK_SEC);
        void getTimelineChunked({
          from: deltaFrom,
          to: desiredTo,
          includeFlows: true
        }).then((response) => {
          if (cancelled) return;
          const mergedRows = mergeTimelineRows(cache.rows, response.rows);
          const mergedAvailable: TimelineWindow = {
            from: Math.min(cache.available.from, response.available.from),
            to: Math.max(cache.available.to, response.available.to)
          };
          const keepSpanSec = Math.max(preset.windowSec * 4, 24 * 3600);
          const trimmedFrom = Math.max(mergedAvailable.from, desiredTo - keepSpanSec);
          const trimmedRows = clipTimelineRows(mergedRows, trimmedFrom, desiredTo);
          timelineHistoryCacheRef.current = {
            from: trimmedFrom,
            to: desiredTo,
            rows: trimmedRows,
            available: mergedAvailable,
            source: response.source
          };
          const window = clampTimelineWindow({
            desiredTo,
            windowSec: preset.windowSec,
            available: mergedAvailable,
            available: mergedAvailable,
            nowSec: safeNow
          });
          setTimeline(clipTimelineRows(trimmedRows, window.from, window.to));
          setTimelineWindow(window);
          setTimelineAvailable(mergedAvailable);
          setTimelineSource(response.source);
        }).finally(() => {
          timelineLoadingRef.current = false;
          if (!background) setTimelineLoading(false);
        });
        return;
      }

      const lookbackSec = timelineFollowNow ? preset.windowSec : preset.windowSec * 4;
      const queryFrom = Math.max(0, desiredTo - lookbackSec);
      void getTimelineChunked({
        from: queryFrom,
        to: desiredTo,
        includeFlows: true
      }).then((response) => {
        if (cancelled) return;
        timelineHistoryCacheRef.current = {
          from: queryFrom,
          to: desiredTo,
          rows: response.rows,
          available: response.available,
          source: response.source
        };
        const window = clampTimelineWindow({
          desiredTo,
          windowSec: preset.windowSec,
          available: response.available,
          nowSec: safeNow
        });
        setTimeline(clipTimelineRows(response.rows, window.from, window.to));
        setTimelineWindow(window);
        setTimelineAvailable(response.available);
        setTimelineSource(response.source);
      }).finally(() => {
        timelineLoadingRef.current = false;
        if (!background) setTimelineLoading(false);
      });
    };
    load();
    const timer = timelineFollowNow && selectedTimeSec === null ? window.setInterval(() => load(true), timelineFollowRefreshMs(preset.windowSec)) : undefined;
    return () => {
      cancelled = true;
      timelineLoadingRef.current = false;
      setTimelineLoading(false);
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedTimelineRange, timelineFollowNow, manualTimelineWindowEndSec, selectedTimeSec]);

  useEffect(() => {
    let disposed = false;

    const flushPatchedStreams = () => {
      const buffered = patchBufferRef.current;
      patchBufferRef.current = null;
      patchTimerRef.current = null;
      if (!buffered || pausedRef.current || selectedTimeSecRef.current !== null) return;
      latestServerOrderRef.current = buffered.order;
      setInterfaces(buffered.interfaces);
      setSummary(buffered.summary);
      setStreams((current) => applyStreamPatchFrozen(current, buffered.upserts, buffered.removes, buffered.order));
    };

    const connect = () => {
      const protocol = window.location.protocol === "https:" ? "wss" : "ws";
      const socket = new WebSocket(`${protocol}://${window.location.host}/ws`);
      socketRef.current = socket;
      setSocketState("connecting");

      socket.onopen = () => {
        if (disposed) return;
        setSocketState("connected");
        socket.send(JSON.stringify({ type: "stream:subscribe", streamKey: selectedStreamKeyRef.current }));
      };

      socket.onclose = () => {
        if (disposed) return;
        socketRef.current = null;
        setSocketState("closed");
        if (reconnectTimerRef.current !== null) {
          window.clearTimeout(reconnectTimerRef.current);
        }
        reconnectTimerRef.current = window.setTimeout(() => {
          reconnectTimerRef.current = null;
          if (!disposed) connect();
        }, 1000);
      };

      socket.onerror = () => {
        if (disposed) return;
        setSocketState("error");
      };

      socket.onmessage = (event) => {
        const message = JSON.parse(event.data) as WsMessage;
        if (message.type === "snapshot") {
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
          latestServerOrderRef.current = message.streams.map((item) => item.streamKey);
          setInterfaces(message.interfaces);
          setSummary(message.summary);
          streamSeqRef.current = message.streamsSeq ?? 0;
          const selectedKey = selectedStreamKeyRef.current;
          if (selectedKey) {
            const selected = message.streams.find((stream) => stream.streamKey === selectedKey) ?? null;
            setSelectedStream(selected ? listItemToStreamState(selected) : null);
          }
        }
        if (message.type === "streams:update") {
          if (!ENABLE_STREAMS_FULL_UPDATE) return;
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
          latestServerOrderRef.current = message.streams.map((item) => item.streamKey);
          setInterfaces(message.interfaces);
          setSummary(message.summary);
          const selectedKey = selectedStreamKeyRef.current;
          if (selectedKey) {
            const selected = message.streams.find((stream) => stream.streamKey === selectedKey) ?? null;
            setSelectedStream(selected ? listItemToStreamState(selected) : null);
          }
        }
        if (message.type === "streams:patch") {
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          const expectedSeq = streamSeqRef.current + 1;
          if (message.seq !== expectedSeq) {
            void getBootstrap()
              .then((bootstrap) => {
                setStreams(bootstrap.streams);
                setInterfaces(bootstrap.interfaces);
                setSummary(bootstrap.summary);
                if (!eventsLoadedRef.current) setEvents(bootstrap.events);
              })
              .catch(() => undefined);
            streamSeqRef.current = message.seq;
            return;
          }
          streamSeqRef.current = message.seq;
          patchBufferRef.current = {
            upserts: message.upserts,
            removes: message.removes,
            order: message.order,
            interfaces: message.interfaces,
            summary: message.summary
          };
          if (patchTimerRef.current === null) {
            patchTimerRef.current = window.setTimeout(flushPatchedStreams, STREAMS_PATCH_APPLY_MS);
          }
        }
        if (message.type === "stream:metrics" && message.streamKey === selectedStreamKeyRef.current && selectedMetricsRangeRef.current === "5m") {
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setSelectedMetrics(message.metrics);
        }
        if (message.type === "events:update") {
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setEvents((current) => {
            const merged = new Map<string, EventLogItem>();
            for (const item of message.events) merged.set(item.id, item);
            for (const item of current) merged.set(item.id, item);
            return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
          });
        }
      };
    };

    connect();

    return () => {
      disposed = true;
      if (patchTimerRef.current !== null) {
        window.clearTimeout(patchTimerRef.current);
        patchTimerRef.current = null;
      }
      patchBufferRef.current = null;
      if (reconnectTimerRef.current !== null) {
        window.clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      socketRef.current = null;
      socket?.close();
    };
  }, []);

  useEffect(() => {
    const socket = socketRef.current;
    if (socket?.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify({ type: "stream:subscribe", streamKey: selectedStreamKey }));
    }
  }, [selectedStreamKey]);

  useEffect(() => {
    const resumed = previousPausedRef.current && !paused;
    previousPausedRef.current = paused;
    if (!resumed) return;

    let cancelled = false;
    void Promise.all([
      getBootstrap(),
      selectedStreamKeyRef.current ? getStream(selectedStreamKeyRef.current) : Promise.resolve(null),
      selectedStreamKeyRef.current ? getStreamMetrics(selectedStreamKeyRef.current, metricsQueryForRange(selectedMetricsRange)) : Promise.resolve(null),
      selectedInterfaceKeyRef.current ? getInterfaceMetricsByKey(selectedInterfaceKeyRef.current) : Promise.resolve(null)
    ]).then(([bootstrap, stream, metrics, interfaceMetrics]) => {
      if (cancelled) return;
      setStreams(bootstrap.streams);
    setEventsRestoreHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
  }, [rightColumnHeight]);

  useEffect(() => {
    const maxHeight = Math.max(MIN_TIMELINE_HEIGHT, leftColumnHeight - 8);
    setTimelineHeight((current) => Math.min(Math.max(current, MIN_TIMELINE_HEIGHT), maxHeight));
    setTimelineRestoreHeight((current) => Math.min(Math.max(current, MIN_TIMELINE_HEIGHT), maxHeight));
  }, [leftColumnHeight]);

  useEffect(() => {
    const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
    setRightPaneWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
    setRightPaneRestoreWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
  }, [workspaceWidth]);

  const dashboardTimeContextActive = !standaloneView && activeTab === "dashboard";
  const dashboardContextTimeSec = dashboardSelectedTimeSec ?? dashboardPauseTimeSec ?? dashboardLatestAvailableTimeSec;
  const activeMetricsRange = dashboardTimeContextActive ? dashboardRange : metricsRange;
  const activeTimelineRange = dashboardTimeContextActive ? dashboardRange : timelineRange;
  const activeEventsRange = dashboardTimeContextActive ? dashboardRange : eventsRange;
  const activeSelectedTimeSec = dashboardTimeContextActive ? dashboardContextTimeSec : selectedTimeSec;
  const activePaused = dashboardTimeContextActive ? dashboardPaused || dashboardContextTimeSec !== null : paused;
  const activeTimelineFollowNow = dashboardTimeContextActive ? !dashboardPaused && dashboardContextTimeSec === null : timelineFollowNow;
  const activeManualTimelineWindowEndSec = dashboardTimeContextActive ? dashboardContextTimeSec : manualTimelineWindowEndSec;

  const {
    streams,
    interfaces,
    timeline,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    summary,
    selectedListItem,
    selectedStream,
    selectedMetrics,
    selectedInterface,
    selectedInterfaceMetrics,
    socketState,
    events,
    bootstrapped
  } = useStreams(
    selectedStreamKey,
    selectedInterfaceKey,
    activePaused,
    activeMetricsRange,
    activeTimelineRange,
    activeEventsRange,
    activeTimelineFollowNow,
    activeManualTimelineWindowEndSec,
    streamSortRefreshToken,
    activeSelectedTimeSec,
    setSelectedStreamKey
  );
  useEffect(() => {
    if (!dashboardTimeContextActive || dashboardPaused || dashboardSelectedTimeSec !== null) return;

    const syncLatestAvailable = () => {
      const latest = summary.updatedAt;
      if (!latest) {
        setDashboardLatestAvailableTimeSec(null);
        return;
      }
      const isFresh = Date.now() / 1000 - latest <= appConfig.staleAfterSec;
      setDashboardLatestAvailableTimeSec(isFresh ? null : latest);
    };

    syncLatestAvailable();
    const timer = window.setInterval(syncLatestAvailable, 1000);
    return () => window.clearInterval(timer);
  }, [appConfig.staleAfterSec, dashboardPaused, dashboardSelectedTimeSec, dashboardTimeContextActive, summary.updatedAt]);

  const loading = !appConfigLoaded || !bootstrapped;
  const timelineInterfaceNames = useMemo(() => {
    const names = new Map<number, string>();
    for (const item of interfaces) {
      if (item.interfaceId !== undefined) names.set(item.interfaceId, item.name);
    }
    return names;
  }, [interfaces]);

  const filteredStreams = useMemo(() => filterStreams(streams, query), [streams, query]);

  const filteredTimeline = useMemo(() => {
    const normalized = query.trim().toLowerCase();

    const candidateRows = normalized
      ? (() => {
          const visible = timeline.filter((row) =>
            matchesSearch([row.kind, row.label, row.streamKey, row.flowKey, row.interfaceName, row.role, row.endpointSrc, row.endpointDst], query)
          );
          const visibleKeys = new Set(visible.map(timelineRowKey));
          const parentKeys = new Set(
            visible
              .filter((row) => row.rowType === "flow")
    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxWidth = Math.max(MIN_RIGHT_WIDTH, width - 8);
      const next = Math.min(maxWidth, Math.max(MIN_RIGHT_WIDTH, startWidth - (moveEvent.clientX - startX)));
      setRightPaneWidth(next);
      if (next > MIN_RIGHT_WIDTH && next < maxWidth) setRightPaneRestoreWidth(next);
    };
    const onUp = () => {
      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const dashboardIsLatestAvailable = dashboardTimeContextActive && dashboardLatestAvailableTimeSec !== null;
  const contextTimeSec = dashboardTimeContextActive ? dashboardContextTimeSec : selectedTimeSec;
  const contextPaused = dashboardTimeContextActive ? dashboardPaused : paused;
  const contextStateLabel = dashboardIsLatestAvailable
    ? " · latest available"
    : dashboardTimeContextActive && dashboardSelectedTimeSec !== null
      ? " · " + formatTimeTravel(dashboardSelectedTimeSec)
      : contextTimeSec !== null
        ? " · " + formatTimeTravel(contextTimeSec)
        : contextPaused
          ? " · display frozen"
          : !summary.updatedAt
            ? " · waiting for data"
            : "";
  const contextUpdatedLabel = "Updated " + (summary.updatedAt ? formatRelativeTime(summary.updatedAt) : "waiting") + contextStateLabel;
  const liveLabel = dashboardIsLatestAvailable ? "Latest available" : contextTimeSec !== null ? "Time travel" : contextPaused ? "Paused" : summary.updatedAt ? "Live" : "Waiting";
  const liveTone = dashboardIsLatestAvailable || contextTimeSec !== null || contextPaused || !summary.updatedAt ? "warning" as const : "success" as const;
  const toggleTheme = () => setTheme((current) => (current === "light" ? "dark" : "light"));
  const toggleLive = () => dashboardTimeContextActive
    ? dashboardContextTimeSec !== null || dashboardPaused ? resumeDashboardLive() : pauseDashboardLive()
    : selectedTimeSec !== null ? resumeLiveTime() : setPaused((current) => !current);

  const renderStatusHeader = (title: string) => (
    <AppContextBar
      compact
      title={title}
      updatedLabel={contextUpdatedLabel}
      socketState={socketState}
      liveLabel={liveLabel}
      liveTone={liveTone}
      onToggleLive={toggleLive}
      onToggleTheme={toggleTheme}
      theme={theme}
    />
  );

  const renderStandaloneSearch = (placeholder: string) => (
    <SearchInput className="standalone-search" value={query} onChange={setQuery} placeholder={placeholder} label="search" />
  );

  const selectGlobalTime = (timeSec: number) => {
    setSelectedTimeSec(timeSec);
    setPaused(true);
    setTimelineFollowNow(false);
    setManualTimelineWindowEndSec(timeSec);
  };

  const resumeLiveTime = () => {
    setSelectedTimeSec(null);
    setPaused(false);
    setTimelineFollowNow(true);
    setManualTimelineWindowEndSec(null);
  };

  const selectDashboardTime = (timeSec: number) => {
    setDashboardSelectedTimeSec(timeSec);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
    setDashboardLatestAvailableTimeSec(null);
  };
  const pauseDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(true);
    setDashboardPauseTimeSec(summary.updatedAt ?? Date.now() / 1000);
    setDashboardLatestAvailableTimeSec(null);
  };
  const resumeDashboardLive = () => {
    setDashboardSelectedTimeSec(null);
    setDashboardPaused(false);
    setDashboardPauseTimeSec(null);
    setDashboardLatestAvailableTimeSec(null);
  };

  const dashboardLayout = dashboardLayouts.find((layout) => layout.id === dashboardLayoutId) ?? dashboardLayouts[0] ?? DEFAULT_DASHBOARD_LAYOUT;
  const dashboardContextLabel = dashboardLatestAvailableTimeSec !== null ? "Latest available" : dashboardSelectedTimeSec !== null ? formatTimeTravel(dashboardSelectedTimeSec) : dashboardPaused ? "Paused" : summary.updatedAt ? "Live" : "Waiting";

  const updateDashboardCell = (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => {
    setDashboardSaveState("idle");
    setDashboardLayouts((layouts) => layouts.map((layout) => layout.id !== dashboardLayout.id ? layout : {
      ...layout,
      cells: layout.cells.map((cell) => cell.id === cellId ? clampDashboardCell(updater(cell), layout.columns) : cell),
      layouts: layout.layouts ? Object.fromEntries(
        (Object.entries(layout.layouts) as [DashboardBreakpoint, DashboardCell[]][]).map(([breakpoint, cells]) => [
          breakpoint,
          cells.map((cell) => cell.id === cellId ? updater(cell) : cell)
        ])
      ) as DashboardResponsiveLayouts : undefined
    }));
  };

  const updateDashboardCellParams = (cellId: string, params: Record<string, string>) => {
    updateDashboardCell(cellId, (cell) => ({ ...cell, params: { ...cell.params, ...params } }));
export type NumericStat = {
  value?: number;
  avg?: number;
  min?: number;
  max?: number;
  count?: number;
};

export type MetricPoint = NumericStat & {
